COLLDATA("silsila","ur",[[3235,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم کے پاس کوئی چیز لائی جاتی تو فرماتے: ”یہ چیز فلاں عورت کو دے آؤ، وہ (میری بیوی) خدیجہ کی سہیلی تھی۔ یہ چیز فلاں کے گھر پہنچا دو کیونکہ وہ خدیجہ سے محبت کرتی تھی۔“","",{"t":"امہات المومنین کے فضائل و مناقب","k":"أخرجه البخاري في ”الأدب المفرد“: ۲۳۲ ، والبزار في ”مسنده“: ۱۹۰۴ - الكشف، والدولابي في ”الذرية الطاهرة“: ق/۱۹ ، والحاكم: ۴/۱۷۵\n(الصحيحة: ۲۸۱۸)"}],[3236,"سیدنا عبداللہ بن عباس رضی اللہ عنہما بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”حضرت مریم بنت عمران کے بعد جنتی عورتوں کی سردار یہ (تین عورتیں:) فاطمہ، خدیجہ اور فرعون کی بیوی آسیہ ہیں۔“","",{"t":"امہات المومنین کے فضائل و مناقب","k":"رواه الطبراني: ۳/۱۵۰ / ۲\n(الصحيحة: ۱۴۲۴)"}],[3237,"رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”خدیجہ کو جنت میں یاقوت والے موتیوں کے گھر کی خوشخبری سنا دو، اس میں شور و غل ہوگا نہ تعب و تھکان۔“ یہ حدیث سیدنا عبداللہ بن ابی اوفی، سیدہ عائشہ، سیدنا ابوہریرہ، سیدنا عبداللہ بن جعفر اور ایک اور صحابی رضی اللہ عنہم سے روایت کی گئی ہے۔","",{"t":"امہات المومنین کے فضائل و مناقب","k":"(۱)۔ أما حديث ابن أبي أوفى: فرواه البخاري: ۱۷۹۲ ، ۳۸۲۹ - واللفظ له - ، ومسلم: ۷/۱۳۳ - والنسائي في ”الكبرى“: ۸۳۶۰ ، وابن أبي شيبة: ۱۲/۱۳۳ ، وابن حبان: ۷۰۰۴ ، وأحمد في ”مسنده“: ۴/۳۵۵ ، ۳۵۶ ، ۳۸۱ وفي ”الفضائل“: ۱۵۷۷ ، ۱۵۸۱ ، ۱۵۸۲ ، وابنه عبدالله في ”زوائده“ على ”الفضائل“: ۱۵۹۳ ، ۱۵۹۴ ، والقطيعي في ”زوائده“ على ”الفضائل“: ۱۵۹۵ ، والحميدي: ۷۲۰ ، والطبراني في ”الكبير“: ۲۳/ رقم ۱۱ (۲)۔ وأما حديث عائشة: فرواه البخاري: ۳۸۲۶ ، ۳۸۲۷ ، ومسلم: ۷/۱۳۳ ، و الترمذي: ۳۸۷۶ ، والنسائي في ”الكبرى“: ۸۳۶۲ ، وأحمد في ”مسنده“: ۶/۵۸ ، ۲۰۲ ، ۲۷۹ ، والحاكم في ”المستدرك“: ۳/۱۸۶ ، وأسحاق بن راهويه في ”مسنده“: ۳۱۱ (۳)۔ وأما حديث أبي هريرة: فرواه البخاري: ۳۸۲۰ ، ۷۴۹۷ ، ومسلم: ۷/۱۳۳ ، والنسائي في ”الكبرى“: ۸۳۵۸ ، وابن أبي شيبة: ۱۲/۱۳۳ ، وابن حبان: ۷۰۰۹ ، والحاكم: ۳/۱۸۵ ، والبغوي: ۳۹۵۳ ، وأحمد في ”المسند“: ۲/۲۳۱ وفي ”الفضائل“: ۱۵۸۸ ، وأبو يعلى: ۶۰۸۹ ، والطبراني: ۲۳/ رقم- ۱۰ (۴)۔ وأما حديث عبدالله بن جعفر: فرواه ابن حبان: ۷۰۰۵ ، والحاكم: ۳/۱۸۴ ، ۱۸۵ ، وأحمد في ”المسند“: ۱/۲۰۵ وفي ”الفضائل“: ۱۵۸۵ ، ۱۵۹۱ ، وأبو يعلى في ”مسنده“: ۶۷۹۵ ، ۶۷۹۷ ، والطبراني في ”المعجم الكبير“: ۲۳/ رقم - ۱۳ (۵)۔ وأما حديث الرجل من الصحابة: فقد رواه ابن أبي شيبة في ”المصنف“: ۱۲/۱۳۴\n(الصحيحة: ۳۶۰۸)","e":"نبی کریم کی دعوت پر سب سے پہلے لبیک کہنے والی، گھبراہٹوں میں آپ صلی اللہ علیہ وسلم کا سہارا بننے والی اور آپ صلی اللہ علیہ وسلم پر اپنا سرمایہ لٹا دینے والی آپ کی وفادار بیوی سیدہ خدیجہ رضی اللہ عنہا تھیں۔ اللہ تعالیٰ نے ان کی قربانیوں کی قدر کی اور انہیں جنت میں گھر کی بشارت سنا دی۔"}],[3238,"نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”مجھے حکم دیا گیا کہ میں (اپنی بیوی) خدیجہ کو جنت میں یاقوت سے بنے ہوئے گھر کی خوشخبری سناؤں، جس میں شور و غل ہوگا نہ دکھ درد۔“ یہ حدیث سیدنا عبداللہ بن جعفر، سیدہ عائشہ، سیدنا ابو ہریرہ، سیدنا عبد اللہ بن ابو اوفی اور کئی صحابہ رضی اللہ عنہم سے مروی ہے۔","",{"t":"امہات المومنین کے فضائل و مناقب","k":"(۱)۔ أما حديث عبدالله بن جعفر: فأخرجه أحمد: ۱/۲۰۵ ، والحاكم: ۳/۱۸۴ ، ۱۸۵ ، والضياء في ”المختارة“: ق ۱/۱۲۸ (۲)۔ وأما حديث عائشة ((دون قوله: لاصحب .....)): فأخرجه أحمد: ۶/۲۷۹ ، وعنه الحاكم: ۳/۱۸۵ ، وكذا الخطيب في ”التاريخ“: ۱۲/۲۳۴ ، ثم اخرجه البخاري: ۳/۱۳ ، ۴/۱۱۶ ، ومسلم: ۷/۱۳۳ ، والترمذي: ۲/۳۲۱ ، وزاد الترمذي: ((لاصحب فيه، ولا نصب)) (۳)۔ وأما حديث أبي هريرة: فأخرجه البخاري: ۳/۱۴ ، ۴/۹۷۹ ، ومسلم أيضا، وأحمد: ۲/۲۳۰ (۴)۔ وأما حديث ابن أبي أوفي: فأخرجه الشيخان ، وأحمد: ۴/۳۵۵ ، ۳۵۶ ، ۳۵۷ ، ۳۸۱\n(الصحيحة: ۱۵۵۴)","e":"سیدہ خدیجہ رضی اللہ عنہا نبوت کا ابتدائی دور ہی پا سکی تھیں، لیکن اس مختصر عرصے میں انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے وفاؤں کا وہ انداز اختیار کیا کہ نبوی دربار سے جنتوں اور بہشتوں کی بشارتیں وصول کر لیں تھیں۔"}],[3239,"سیدہ عائشہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے انھیں فرمایا: ”مجھ پر موت کی سختیاں اس بنا پر آسان ہو رہی ہیں کہ تم جنت میں مجھے اپنی بیوی دکھائی دے رہی ہو۔“","",{"t":"امہات المومنین کے فضائل و مناقب","k":"رواه الحسين المروزي في ”زوائد الزهد“: ۷/۲ ، والخلعي في ”الفوائد“: ۲/۵۹ / ۱ ، وأحمد: ۶/۱۳۸\n(الصحيحة: ۲۸۶۷)","e":"اس میں سیدہ عائشہ رضی اللہ عنہا کی عظیم منقبت بیان کی گئی ہے کہ وہ جنت میں نہ صرف آپ صلی اللہ علیہ وسلم کی بیوی ہوں گے، بلکہ آپ صلی اللہ علیہ وسلم اس چیز پر اتنے خوش ہیں کہ آپ صلی اللہ علیہ وسلم کو موت کے سکرات اور سختیاں ہلکی محسوس ہو رہی ہیں۔"}],[3240,"سیدنا مسلم بطین رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”عائشہ جنت میں بھی میری بیوی ہوگی۔“","",{"t":"امہات المومنین کے فضائل و مناقب","k":"أخرجه ابن سعد: ۸/۶۶\n(الصحيحة: ۱۱۴۲)"}],[3241,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدہ فاطمہ رضی اللہ عنہا کا ذکر کیا، میں نے ان کے بارے میں کوئی (ناگوار) باتیں کر دیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”کیا تم اس شرف پر راضی نہیں ہوگی کہ دنیا و آخرت میں میری بیوی ہو؟“ میں نے کہا: کیوں نہیں، اے اللہ کے رسول! آپ صلی اللہ علیہ وسلم نے فرمایا: ”تم دنیا و آخرت میں میری بیوی ہو۔“","",{"t":"امہات المومنین کے فضائل و مناقب","k":"أخرجه ابن حبان: ۷۰۵۳ - الأحسان، ، والحاكم: ۴/۱۰ ، وأخرج الترمذي: ۳۸۷۵ ، وابن حبان: ۷۰۵۲ الجملة الاخيرة منه عن عائشة رضي الله عنها\n(الصحيحة: ۳۰۱۱)","e":"اس میں سیدہ عائشہ رضی اللہ عنہا کی کمال فضیلت بیان کی گئی ہے کہ وہ دنیا میں بھی ام المومنین ہیں اور آخرت میں بھی زوجہ رسول ہی رہیں گی۔ نبی کریم صلی اللہ علیہ وسلم نے سیدہ کو یہ مژدہ اس وقت سنایا جب انھوں نے بتقاضہ بشریت آپ صلی اللہ علیہ وسلم کی محبوب بیٹی سیدہ فاطمہ رضی اللہ عنہا پر کچھ نقد کیا تھا۔ معلوم ہوا کہ ہمیں یہ حق نہیں پہنچتا کہ ہم صحابہ کرام اور صحابیات عظام کے آپس کے اعتراضات کو ان کا دور گزر جانے کے بعد موضوع بحث بنائیں۔"}],[3242,"رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”عورتوں پر عائشہ کی فضیلت اس طرح ہے جس طرح تمام کھانوں پر ثرید کی فضیلت ہے۔“","",{"t":"امہات المومنین کے فضائل و مناقب","k":"ورد من حديث أنس وأبي موسى و عائشة: ۱ - وأما حديث أنس: فأخرجه البخاري: ۳۷۷۰ ، ۵۴۱۹ ، ۵۴۲۸ ، ومسلم: ۷/۱۳۸ ، والترمذي في ”السنن“: ۳۸۸۷ - وصححه - ، والدارمي في ”السنن“: ۲/۱۰۶ ، والنسائي في ”السنن الكبرى“: ۶۶۹۲ ، وابن ماجه: ۳۲۸۱ ، وأحمد في ”المسند“: ۳/۱۵۶ ۲ - وأما حديث أبي موسى: فأخرجه البخاري: ۳۷۶۹ ، ومسلم: ۷/۱۳۲ - ۱۳۳ ، والنسائي: ۸۳۸۱ ، ۸۸۹۵ ، والترمذي: ۱۸۳۴ - وصححه - ، والطيالسي: ۵۰۴ ، وكذا ابن ماجه: ۳۲۸۰ ، وأحمد: ۴/۳۹۴ ۳ - وأما حديث عائشة: فأخرجه النسائي: ۸۸۹۶\n(الصحيحة: ۳۵۳۵)","e":"ثرید ایک قسم کا زود ہضم اور بابرکت کھانا ہوتا ہے جسے دوسرے کھانوں پر ترجیح دی جاتی ہے۔ یہی معاملہ سیدہ عائشہ رضی اللہ عنہا کا ہے کہ وہ مسلم خواتین میں اعلی مقام رکھتی ہیں۔"}],[3243,"حضرت ابو سلمہ بن عبد الرحمن کہتے ہیں کہ میں سیدہ عائشہ رضی اللہ عنہا کے پاس گیا، انھوں نے مجھے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میرے بعد پیش آنے والے تمھارے معاملات نے مجھے مغموم و بے چین کر رکھا ہے اور صبر کرنے والے ہی تم پر صبر کریں گے۔“ پھر سیدہ عائشہ نے ابو سلمہ سے کہا: اللہ تعالیٰ تیرے باپ کو جنت کی سلسبیل سے مشروب پلائے۔ انھوں نے واقعی صلہ رحمی کا ثبوت دیتے ہوئے امہات المومنین کو (ایک باغ) دیا، جو چالیس ہزار کا فروخت کیا گیا۔","",{"t":"امہات المومنین کے فضائل و مناقب","k":"أخرجه الحاكم: ۳/۳۱۲\n(الصحيحة: ۱۵۹۴)","e":"امام البانی رحمہ اللہ نے اس حدیث کا ایک شاہد یہ بھی نقل کیا ہے: سیدہ ام سلمہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی بیویوں سے فرمایا: «إِنَّ الَّذِي يَحْنُو عَلَيْكُنَّ بَعْدِي هُوَ الصَّادِقُ الْبَارُّ، اللَّهُمَّ اسْقِ عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ مِنْ سَلْسَبِيلِ الْجَنَّةِ -» (حاکم) ..... ”(میری بیویو!) بیشک جو آدمی تم پر شفقت و مہربانی کرے گا، وہی سچا اور نیک ہوگا، اے اللہ! تو عبد الرحمن بن عوف کو جنت کی سلسبیل سے سیراب فرما دے۔“ معلوم ہوا کہ نبی کریم صلی اللہ علیہ وسلم کی وفات کے بعد آپ صلی اللہ علیہ وسلم کی بیویوں کا انتہائی درجہ کا احترام و اکرام اور ان کے ساتھ شفقت و رافت والا معاملہ ہونا چاہیے۔ آج اگرچہ امہات المومنین موجود نہیں ہیں، لیکن ان کا تذکرہ خیر کرنا اور ان کے بشری تقاضوں کو سامنے رکھ کر ان پر کیچڑ نہ اچھالنا ہمارے ایمان و ایقان کا تقاضا ہے۔"}],[3244,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تم میں سے بہتر وہ ہے جو میرے بعد میرے اہل کے حق میں بہتر ہوگا۔“","",{"t":"آپ کے اہل و عیال کے حق میں بہتر آدمی کی فضیلت","k":"أخرجه البزار: ص- ۲۷۴ - زوائده، وأبو نعيم في ”أخبار أصبهان“: ۲/۲۹۴ ، والحاكم: ۳/۳۱۱\n(الصحيحة: ۱۸۴۵)","e":"آپ صلی اللہ علیہ وسلم کی بیویوں، بیٹیوں اور دوسرے اہل بیت کے ساتھ حسن سلوک کرنا آپ صلی اللہ علیہ وسلم کی اطاعت و فرمانبرداری کی ایک شکل ہے۔"}],[3245,"سیدنا عبداللہ بن عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے زمین پر چار خطوط کھینچے، پھر پوچھا: ”کیا تم ان لکیروں کے بارے میں جانتے ہو؟“ انھوں نے کہا: اللہ تعالیٰ اور اس کا رسول ہی بہتر جانتے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: ”جنت والی خواتین میں سب سے افضل یہ چار ہیں: خدیجہ بنت خویلد، فاطمہ بنت محمد (صلی اللہ علیہ وسلم)، مریم بنت عمران اور فرعون کی بیوی آسیہ بنت مزاحم۔“","",{"t":"جنت کی چار افضل خواتین","k":"رواه أحمد: ۱/۲۹۳ ، والطحاوي في ”المشكل“: ۱/۵۰ ، والحاكم: ۲/۵۹۴ ، ۳/۱۶۰ ، ۱۸۵ ، والضياء في ”المختارة“: ۶۵/۶۷ - ۱ ، والطبراني: رقم ۱۱۹۲۸ ، ۱۲۱۷۹\n(الصحيحة: ۱۵۰۸)"}],[3246,"سیدہ عائشہ رضی اللہ عنہا کہتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرحان و شادماں دیکھ کر کہا: اے اللہ کے رسول! میرے لیے اللہ تعالیٰ سے دعا کر دیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اے اللہ! عائشہ کے پہلے اور پچھلے اور اعلانیہ اور مخفی (سب) گناہ بخش دے۔“ (خوشی سے) سیدہ عائشہ رضی اللہ عنہا نے ہنسنا شروع کر دیا، یہاں تک کہ ان کا سر رسول اللہ صلی اللہ علیہ وسلم کی گودی میں جا پڑا۔ آپ صلی اللہ علیہ وسلم نے پوچھا: ”کیا تجھے میری دعا نے خوش کر دیا ہے؟“ انھوں نے کہا: بھلا مجھے آپ کی دعا خوش کیوں نہ کرے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ کی قسم! میں ہر نماز میں اپنی امت کے لیے یہ دعا کرتا ہوں۔“","",{"t":"سیدہ عائشہ رضی اللہ عنہا کے لیے دعائے مغفرت","k":"أخرجه أخرجه البزار في ”مسنده“: ۲۶۵۸ ، كشف الأستار\n(الصحيحة: ۲۲۵۴)"}],[3247,"سیدہ ربیعہ اسلمی رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت کیا کرتا تھا، آپ نے مجھے زمین دی اور ابو بکر رضی اللہ عنہ کو بھی زمین دی۔ ہم پر دنیا غالب آ گئی، کھجور کے ایک درخت کے بارے میں ہمارا جھگڑا ہو گیا۔ ابو بکر رضی اللہ عنہ نے کہا: یہ میری زمین کی حد میں ہے۔ میں نے کہا: یہ میری حد میں ہے۔ میرے اور ابو بکر رضی اللہ عنہ کے درمیان سخت کلامی ہوئی، ابو بکر رضی اللہ عنہ نے ایسا کلمہ کہا جس کو میں نے ناپسند کیا اور وہ خود بھی شرمندہ ہوئے۔ (بالآخر) انھوں نے مجھے کہا: اے ربیعہ! مجھے یہی کلمہ کہو تا کہ بدلہ ہو جائے۔ لیکن میں نے کہا کہ میں ایسا نہیں کروں گا۔ ابو بکر رضی اللہ عنہ نے کہا: تجھے ضرور کہنا پڑے گا، ورنہ میں رسول اللہ صلی اللہ علیہ وسلم سے فریاد کروں گا۔ میں نے کہا میں ایسا (جملہ) نہیں کہوں گا۔ ربیعہ کہتے ہیں: ابو بکر زمین چھوڑ کر نبی کریم صلی اللہ علیہ وسلم کی طرف چل دیے، میں بھی ان کے پیچھے چل پڑا۔ بنو اسلم قبیلہ کے چند لوگ آئے اور انھوں نے کہا: اللہ، ابو بکر رضی اللہ عنہ پر رحم کرے، بھلا وہ رسول اللہ صلی اللہ علیہ وسلم سے کس چیز کے متعلق تیرے خلاف فریاد کریں گے۔ حالانکہ انھوں نے تجھے ایسے ایسے بھی کہا ہے۔ میں نے کہا: تم جانتے ہو کہ یہ کون ہے؟ یہ ابو بکر صدیق رضی اللہ عنہ ہیں، (غار ثور) میں دو میں سے دوسرے وہ تھے اور وہ مسلمانوں کے بزرگ ہیں۔ پس تم بچو (کہیں ایسا نہ ہو) کہ وہ تم کو اپنے خلاف میری مدد کرتے ہوئے دیکھ کر غصے ہو جائیں، پھر وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس جائیں اور آپ اس کے غصے کی وجہ سے ناراض ہو جائیں اور پھر اللہ تعالیٰ ان دونوں کی ناراضگی کی وجہ سے ناراض ہو جائیں اور ربیعہ ہلاک ہو جائے۔ انھوں نے کہا: تو (پھر ایسے میں) تم ہمیں کیا حکم دیتے ہو؟ اس نے کہا: تم چلے جاؤ۔ (اب ہوا یوں کہ) ابو بکر رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کی طرف چلے اور میں بھی اکیلا ان کے پیچھے چل پڑا۔ پس وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئے اور جیسی بات تھی ویسے ہی بیان کر دی۔ آپ صلی اللہ علیہ وسلم نے اپنا سر میری طرف اٹھایا اور فرمایا: ”اے ربیعہ تیرے اور صدیق کے مابین کیا معاملہ ہے؟“ میں نے کہا: اے اللہ کے رسول! معاملہ تو ایسے ایسے تھا۔ سیدنا ابو بکر رضی اللہ عنہ نے مجھے ایسا کلمہ کہا جس کو میں نے ناپسند کیا، پھر انھوں نے مجھے یہ بھی کہا کہ میں بھی ان کو وہی بات کہ دوں تاکہ لے پلے ہو جائے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ٹھیک ہے، اب تم نے (قصاصا) وہ بات نہیں دہرانی، بلکہ یوں کہنا ہے: اے ابو بکر! اللہ تجھے معاف کرے۔ اے ابو بکر! اللہ تجھے معاف کرے۔“ جب سیدنا ابو بکر رضی اللہ عنہ وہاں سے چلتے تو وہ رو رہے تھے۔","",{"t":"سیدنا ابو بکر صدیق رضی اللہ عنہ کی فضیلت و عظمت","k":"أخرجه أحمد: ۴/۵۸ - ۵۹ ، والطبراني في ”المعجم الكبير“: ۴۵۷۷\n(الصحيحة: ۳۲۵۸)","e":"غلطی یا ناراضگی ناممکن نہیں، بلکہ یہ انسان کی فطرت ہے، آدمی جذبات میں آ کر نامناسب باتیں بھی کہہ دیتا ہے، لیکن نیک صفت لوگ جذبات میں ہونے والی غلطیوں کو ندامت کے آنسوؤں سے فوراً دھو لیتے ہیں، حضرات صحابہ کرام رضوان اللہ علیہم اجمعین میں بھی ناراضگی ہو جاتی تھی، مگر وہ نفوس قدسیہ تقویٰ کی بلندیوں پر فائز ہونے کی وجہ سے فوراً اپنا معاملہ رفع دفع کرتے ہوئے دل صاف کر لیتے تھے۔ اس حدیث طیبہ سے جہاں سیدنا ابو بکر صدیق رضی اللہ عنہ کی عزت و عظمت اور مقام و مرتبہ معلوم ہوتا ہے، وہاں یہ بھی واضح ہوتا ہے کہ آپ حد درجہ رقیق القلب اور خوف خدا، خشیت الہی اور احترام انسانیت رکھنے والے شخص تھے۔ سیدنا ابو بکر صدیق اور سیدنا ربیعہ رضی اللہ عنہما دونوں نے جھگڑا تو برابر کا کیا، ہاں یہ بات ہے کہ ابو بکر رضی اللہ عنہ نے آخر میں ندامت کا اظہار کیا اور مقابل کو کہا کہ وہ یہی بات کر کے اس سے قصاص لے لے۔ لیکن سیدنا ربیعہ رضی اللہ عنہ کو ڈانٹنے کا مقصد یہ تھا کہ ابو بکر صدیق بزرگ ہیں، ان کا مقام و مرتبہ زیادہ ہے، اس لیے عام صحابہ کو ان کا لحاظ کرنا چاہیے اور ان سے کٹ حجتی کرنے سے باز رہنا چاہیے۔ جیسا کہ سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «أَقِيلُوا ذَوِي الْهَيْئَاتِ عَثَرَاتِهِمْ إِلَّا الْحُدُودَ -» ..... ”صاحب حیثیت لوگوں کی غلطیاں معاف کر دیا کرو، الا یہ کہ وہ حدود ہوں۔“ (صحیحہ: ۶۳۸) دنیا کا ہر وہ معاشرہ جس کو تہذیب و شائستگی سے ادنیٰ تعلق بھی رہا ہو، اپنے اندر موجود باوقار، شریف النفس اور رذائل سے دور رہنے والے افراد کو قدر کی نگاہ سے دیکھتا ہے اور ان کی چھوٹی چھوٹی کوتاہیوں اور فروگذاشتوں کو نظر انداز کرتا نظر آتا ہے۔"}],[3248,"سیدنا ابو الدرداء رضی اللہ عنہ کہتے ہیں: میں نبی کریم صلی اللہ علیہ وسلم کے پاس بیٹھا ہوا تھا، اچانک سیدنا ابو بکر رضی اللہ عنہ تشریف لائے، انھوں نے اپنی چادر کا کنارہ پکڑا ہوا تھا، حتیٰ کہ اسے اپنے گھٹنے سے ہٹا دیا۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”تمھارے ساتھی نے خود کو مصائب و مشکلات میں ڈال دیا ہے۔“ انھوں نے سلام کہا اور عرض کی: اے اللہ کے رسول! میری ابن خطاب سے کچھ گڑبڑ ہو گئی، میں نے جلدی میں کچھ کہہ دیا، پھر مجھے ندامت ہوئی، سو میں نے ان سے کہا کہ وہ مجھے معاف کر دیں، لیکن انھوں نے ایسا کرنے سے انکار کر دیا، اس لیے اب میں آپ کی طرف آیا ہوں۔ آپ صلی اللہ علیہ وسلم نے تین دفعہ فرمایا: ”ابو بکر! اللہ تجھے معاف کرے۔“ ادھر بعد میں سیدنا عمر رضی اللہ عنہ کو ندامت ہوئی، وہ سیدنا ابو بکر کے گھر گئے اور پوچھا: کیا ابو بکر ہیں؟ انھوں نے کہا: نہیں۔ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئے، آپ صلی اللہ علیہ وسلم کا چہرہ بدلتا گیا، حتیٰ کہ ابو بکر ڈرنے لگ گئے، وہ گھٹنوں کے بل بیٹھ گئے اور کہا: اے اللہ کے رسول! اللہ کی قسم! میں زیادہ ظلم کرنے والا تھا۔ (دو دفعہ کہا)۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”لوگو! بیشک اللہ نے مجھے تمھاری طرف بھیجا، لیکن تم نے مجھے (جھٹلاتے ہوئے) کہا: آپ جھوٹ بولتے ہیں۔ تو ابو بکر رضی اللہ عنہ نے کہا: آپ سچے ہیں۔ ابو بکر نے اپنے جان و مال کو میری حمایت میں لگا دیا، کیا تم میرے دوست کو میرے لیے چھوڑ دو گے؟“ (دو دفعہ فرمایا) اس کے بعد انھیں تکلیف نہیں پہنچائی گئی۔","",{"t":"سیدنا ابو بکر صدیق رضی اللہ عنہ کی فضیلت و عظمت","k":"أخرجه البخاري: ۷/۱۸ / ۳۶۶۱\n(الصحيحة: ۳۱۴۴)"}],[3249,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ سیدنا ابو بکر رضی اللہ عنہ، رسول اللہ صلی اللہ علیہ وسلم کے پاس تشریف لائے، آپ نے فرمایا: ”تم اللہ تعالیٰ کے آگ سے آزاد شدہ آدمی ہو۔“","",{"t":"سیدنا ابو بکر صدیق رضی اللہ عنہ کی فضیلت و عظمت","k":"أخرجه الترمذي: ۲/۲۹۲ ، والطبراني في ”المعجم الكبير“: رقم - ۹ ، والحاكم: ۳/۳۷۶\n(الصحيحة: ۱۵۷۴)"}],[3250,"سیدنا عبداللہ بن عباس رضی اللہ عنہما سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”کوئی بھی نہیں جو مجھ پر ابو بکر رضی اللہ عنہ کی نسبت زیادہ احسان کرنے والا ہو، انھوں نے جان و مال کو میری حمایت میں صرف کر دیا اور اپنی بیٹی (عائشہ) کی مجھ سے شادی بھی کی۔“","",{"t":"سیدنا ابو بکر صدیق رضی اللہ عنہ کی فضیلت و عظمت","k":"أخرجه الطبراني في ”معجمه الكبير“: ۱۱/۱۹۱ / ۱۱۴۶۱ ، وابن عدي: ۳/۲ ، وابن عساكر في ”تاريخه“: ۹/۲۷۸ / ۱ ، وأخرجه البخاري: ۴۶۷ بلفظ: ((انه ليس من الناس احد امن على في نفسه وماله من ابي بكر ابن ابي قحافة، ولو كنت متخذا .....))\n(الصحيحة: ۲۲۱۴)"}],[3251,"سیدنا عبداللہ بن حنطب رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے سیدنا ابو بکر اور سیدنا عمر رضی اللہ عنہما کو دیکھ کر فرمایا: ”یہ (میری امت کے) کان اور آنکھیں ہیں۔“","",{"t":"سیدنا ابو بکر صدیق رضی اللہ عنہ کی فضیلت و عظمت","k":"أخرجه الترمذي: ۴/۳۱۱\n(الصحيحة: ۸۱۴)","e":"یعنی سر میں جو اہمیت کان اور آنکھ کی ہے وہ مرتبہ اسلام میں صدیق و فاروق کی ہے، کانوں اور آنکھوں کے بغیر انسان کیسا لگتا ہے؟ اس کی کتنی وقعت ہوتی ہے؟ وہ اپنی صلاحیتوں سے کس قدر مستفید ہو سکتا ہے؟ یہی حشر اس اسلام کا ہوگا، جس میں رسول اللہ صلی اللہ علیہ وسلم کے سر صدیق و فاروق نہیں ہوں گے۔"}],[3252,"رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ابو بکر اور عمر پہلے اور پچھلے لوگوں میں سے جنت میں داخل ہونے والے ادھیڑ عمر والے لوگوں کے سردار ہیں۔“ یہ حدیث صحابہ کی ایک جماعت سے مروی ہے، مثلاً: سیدنا علی بن ابو طالب، سیدنا انس بن مالک، سیدنا ابو جحیفہ، سیدنا جابر بن عبد اللہ اور سیدنا ابو سعید خدری رضی اللہ عنہم۔","",{"t":"سیدنا ابو بکر صدیق رضی اللہ عنہ کی فضیلت و عظمت","k":"۱ - أما حديث علي: فأخرجه الترمذي: ۴/۳۱۰ ، وابن ماجه: ۱/۴۹ ، وابن عدي: ۲/۲۱۴ ، وابن شاهين في ”السنة“: ۶۷ - نسختي، والخطيب في ”تاريخ بغداد“: ۱۰/۱۹۲ ، وابن عساكر في ”تاريخ دمشق“: ۹/۳۰۷ / ۲ ، والدولابي في ”الكنى“: ۲/۹۹ ، وابن عدي ” ۲/۱۰۰ ، وعبد الغني المقدسي في ”الاكمال“: ۱/۲۱۴ / ۲ ، وابن عساكر: ۹/۳۱۰ / ۱ ، وعبدالله بن أحمد في ”زوائد المسند“: ۱/۸۰ ۲ - وأما حديث أنس: فأخرجه الترمذي: ۴/۳۱۰ ، والضياء المقدسي في ”المختارة“: ۱۹۷ - ۱۹۸ ، وابن عساكر: ۲/۱۲۵۰ / ۱ ، ۹/۳۱۰ / ۱ ، ۱۳/۲۴ / ۱ ، وابن عساكر: ۹/۳۱۰ / ۲ ، والضياء: ۲/۱۴۵ ۳ - وأما حديث أبي جحيفة عن أبيه: فأخرجه ابن حبان: ۲۱۹۲ ، وكذا ابن ماجه: ۱/۵۱ ، والدولابي في ”الكنى“: ۱/۱۲۰ ۴ - وأما حديث جابر: فرواه الطبراني في ”الأوسط“، قال البيهقي: ۹/۵۳ ، ومن هذا الوجه أخرجه ابن عساكر: ۱۳/۲۴ / ۱ ۵ - وأما حديث أبي سعيد: فرواه الطبراني في ”الأوسط“ ۶ - أما حديث ابن عمر: فأخرجه السهمي في ”تاريخ جرجان“: ۷۷ ، وابن عساكر: ۱۳/۲۳ / ۲ ، وقال ابن أبي حاتم: ۲/۳۸۹\n(الصحيحة: ۸۲۴)","e":"صدیق و فاروق ان کے سردار ہوں گے، جو لوگ ادھیڑ عمری میں فوت ہو کر جنت میں داخل ہوں گے، وگرنہ جنت میں تو سب جنتیوں کی عمریں، جوانیاں اور قد و قامت وغیرہ برابر ہوں گے۔ ہم نے حدیث کے لفظ ”کھول“ کا معنی ادھیڑ عمر والے لوگ کیا ہے، جبکہ قاموس میں ہے کہ تیس یا چالیس برس سے لے کر اکاون برس تک کی عمر والوں کو ”کھول“ کہتے ہیں۔ امام ترمذی نے اپنے باب میں واضح کیا ہے کہ صدیق و فاروق جن لوگوں کے سردار ہوں گے، ان میں انبیا و رسل داخل نہیں ہیں۔"}],[3253,"جب سیدنا انس بن مالک رضی اللہ عنہ سے رسول اللہ صلی اللہ علیہ وسلم کے خضاب کے بارے میں پوچھا گیا، تو انھوں نے کہا: رسول اللہ کے چند بال ہی سفید ہوئے تھے، البتہ آپ کے بعد سیدنا ابو بکر اور سیدنا عمر رضی اللہ عنہما نے مہندی اور کتم (کے پودے) کو خضاب کے لیے استعمال کیا۔ (یہ بات بھی یاد رہے کہ) جب ابو بکر اپنے باپ سیدنا ابو قحافہ رضی اللہ عنہ کو فتح مکہ والے دن رسول اللہ صلی اللہ علیہ وسلم کے پاس لائے تو آپ صلی اللہ علیہ وسلم نے ابو بکر سے فرمایا: ”اگر تم اپنے بزرگوں کو اپنے مقام پر ہی رہنے دیتے تو ہم ابو بکر کی عزت کرتے ہوئے ان کے پاس جاتے۔“ پھر انھوں نے اسلام قبول کر لیا، ان کی داڑھی اور سر کے بال ثغامہ بوٹی کی طرح سفید تھے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”دونوں (یعنی داڑھی اور سر) کے بالوں کا رنگ بدل دو اور سیاہ رنگ سے اجتناب کرو۔“","",{"t":"سیدنا ابو بکر صدیق رضی اللہ عنہ کی فضیلت و عظمت","k":"أخرجه الامام أحمد: ۳/۱۶۰ ، والحاكم: ۳/۲۴۴ ، وابو يعلى: ۲۸۳۱\n(الصحيحة: ۴۹۶)","e":"ثغامہ: ایک درخت جو پہاڑ کی چوٹی پر اگتا ہے، اس کا پھل اور پھول سفید ہوتے ہیں اور خشک ہونے کی صورت میں سفیدی بڑھ جاتی ہے۔ نبی کریم صلی اللہ علیہ وسلم کی خواہش یہ تھی کہ ابو بکر کے احترام کا تقاضا یہ ہے کہ آپ صلی اللہ علیہ وسلم خود ان کے والد گرامی قدر کے پاس چلے جاتے۔"}],[3254,"رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”خبردار! میں ہر گہرے دوست کی دوستی سے بری ہو رہا ہوں، اگر میں نے کسی (بشر) کو خلیل بنانا ہوتا تو ابو بکر کو بناتا، تمھارا ساتھی (یعنی حضرت محمد صلی اللہ علیہ وسلم) اللہ تعالیٰ کا خلیل ہے۔“ یہ حدیث سیدنا عبد اللہ بن مسعود، سیدنا عبد اللہ بن عباس، سیدنا ابو سعید خدری، سیدنا عبد اللہ بن زبیر، سیدنا ابو معلی انصاری، سیدنا جندب بجلی، سیدنا ابو ہریرہ، سیدہ عائشہ، سیدنا انس، سیدنا جابر، سیدنا ابو واقد اور سیدنا براء رضی اللہ عنہم سے مروی ہے۔","",{"t":"سیدنا ابو بکر صدیق رضی اللہ عنہ کی فضیلت و عظمت","k":"جاء من جمع من الصحابة: (۱)۔ أما حديث ابن مسعود: فرواه مسلم: ۷/۱۰۸ ، ۱۰۹ ، والترمذي: ۳۶۵۵ ، وابن ماجه: ۹۳ ، ..... (۲)۔ وأما حديث ابن عباس: فقد رواه البخاري: ۴۶۷ ، والنسائي في ”الكبرى“: ۸۱۰۲ ، ..... (۳)۔ وأما حديث أبي سعيد الخدري: فقد رواه البخاري: ۴۶۶ ، ومسلم: ۷/۱۰۸ ، ..... (۴)۔ وأما حديث عبدالله بن الزبير: فقد أخرجه البخاري في ”صحيحه“: ۳۶۵۸ (۵)۔ وأما حديث أبي المُعلَّى بن لَوْذَانَ: فقد رواه الترمذي: ۳۶۵۹ ، وأحمد: ۳/۴۷۸ ، ۴/۲۱۱ ، ..... (۶)۔ وأما حديث جندب بن عبدالله البجلي: فقد رواه مسلم: ۷/۱۰۸ ، ..... (۷)۔ وأما حديث عائشة: فرواه أحمد في ”الفضائل“: ۵۶۵ ، والطبراني في ”المعجم الأوسط“: ۲۰۵۵ (۸)۔ وأما حديث أنس: فرواه الطبراني في ”مسند الشاميين“: ۱۵۴ ، والبزار في ”مسنده“: ۲۴۸۴ (۹)۔ وأما حديث جابر: فرواه عبدالله ابن أحمد في ”زوائده“ على ”فضائل الصحابة“: ۲۱ (۱۰)۔ وأما حديث أبي واقد الليثي: فرواه الطبراني في ”الكبير“: ۳۲۹۷ (۱۱)۔ وأما حديث البراء: فرواه الخطيب في ”تاريخه“: ۳/۱۳۴ (۱۲)۔ وأما حديث أبي هريرة: فقد أخرجه الترمذي: ۳۶۶۱ ، .....\n(الصحيحة: ۳۵۹۸)","e":"”خلیل“ اس مُحب کو کہتے ہیں جو اپنے دل میں اپنے محبوب سے اتنی زیادہ پکی اور گہری محبت رکھتا ہو کہ اب مزید اس کے دل میں کسی کے لیے کوئی گنجائش باقی نہ رہی ہو۔ ایسی محبت کو ”خُلّت“ کہتے ہیں اور محبت کا یہ انداز صرف اللہ تعالیٰ کے بارے میں اختیار کیا جاتا ہے، حدیث کا مفہوم یہ ہے کہ نبی کریم صلی اللہ علیہ وسلم کو اللہ تعالیٰ سے جو شدید محبت (یعنی خُلّت) تھی وہ ابو بکر رضی اللہ عنہ سے نہ تھی، کیونکہ صدیق کا مقام و مرتبہ اپنی جگہ پر مسلّم ہے، لیکن اللہ تعالیٰ سے کسی کا کوئی موازنہ اور تقابل نہیں کیا جا سکتا۔ ہاں محمد رسول اللہ صلی اللہ علیہ وسلم نے ابو بکر رضی اللہ عنہ کے لیے اسلامی مودّت و محبت کا دعویٰ بحال رکھا، جس کا مرتبہ ”خُلّت“ سے کم ہے۔ (حافظ ابن حجر نے ”خلیل“ کے نو معانی ذکر کیے ہیں۔ دیکھیں: فتح الباری: حدیث ۳۶۵۴ کے تحت)"}],[3255,"رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میرے بعد ابو بکر اور عمر کی پیروی کرنا، عمار کی سیرت اختیار کرنا اور ابن مسعود کے عہد کو تھام لینا۔“ یہ حدیث سیدنا عبد اللہ بن مسعود، سیدنا حذیفہ بن یمان، سیدنا انس بن مالک اور سیدنا عبد اللہ بن عمر رضی اللہ عنہم سے روایت کی گئی ہے۔","",{"t":"سیدنا ابو بکر صدیق رضی اللہ عنہ کی فضیلت و عظمت","k":"۱ - أما حديث ابن مسعود: فأخرجه الترمذي: ۲/۳۱۱ ، والحاكم: ۳/۷۵ ۲ - وأما حديث حذيفة: أخرجه الترمذي: ۲/۲۹۰ ، والطحاوي في ”المشكل“: ۲/۸۳ - ۸۴ ، وأحمد: ۵/۳۸۵ ، ۴۰۲ ، والحميدي في ”مسنده“: ۱/۲۱۴ / ۲۴۹ ، وابن سعد: ۲/۳۳۴ ، وابن أبي عاصم في ”السنة“: ۱۰۴۸ و ۱۰۴۹ - بتحقيقي، وأبو نعيم في ”الحلية“: ۹/۱۰۹ ، و الخطيب: ۲/۷۰ ، والحاكم: ۳/۷۵ ، وابن عساكر: ۹/۳۲۳ / او ۱۲/۳۱ / ۱ مختصرا او مطولا، وبعضم ذكر المولى، وبعضم لم يذكره، وهو الذي رجحه الحاكم خلافا لأبي حاتم في: العلل“ ۲/۳۸۱ ۳ - وأما حديث أنس بن مالك: فأخرجه ابن عدي: ۱/۷۵ ۴ - وأما حديث ابن عمر: فأخرجه ابن عساكر: ۹/۳۲۳ / ۲\n(الصحيحة: ۱۲۳۳)","e":"دوسری احادیث کی روشنی میں یہ کہنا درست ہے کہ خلفائے راشدین اور صحابہ کرام کی اطاعت کی جائے گی، جب تک اللہ تعالیٰ اور رسول اللہ صلی اللہ علیہ وسلم کی نافرمانی نہ ہو۔"}],[3256,"رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”حرا! تھم جا، نہیں ہے تجھ پر مگر نبی یا صدیق یا شہید۔“ یہ حدیث سیدنا سعید بن زید، سیدنا عثمان بن عفان، سیدنا انس بن مالک، سیدنا بریدہ بن حصیب اور سیدنا ابو ہریرہ رضی اللہ عنہم سے روایت کی گئی ہے۔","",{"t":"سیدنا ابو بکر صدیق رضی اللہ عنہ کی فضیلت و عظمت","k":"۱ - أما حديث سعيد بن زيد: فأخرجه أبو داود: ۲/۲۶۴ ، والترمذي: ۴/۳۳۶ ، وابن ماجه: ۱/۶۱ ، وابن حبان: ۹/۶۹ - ۶۹۵۷ / الاحسان، والحاكم: ۳/۴۵۰ ، وأحمد: ۱/۱۸۷ و ۱۸۸ و ۱۸۹ ۲ - وأما حديث عثمان: فأخرجه ابن حبان: ۲۱۶۸ ، والترمذي: ۴/۳۲۰ ۳ - وأما حديث أنس: فأخرجه الخطيب في ”التاريخ“: ۵/۳۶۵ ، واخرجه البخاري: ۷/۳۰ ، والترمذي: ۴/۳۱۸ ، واحمد: ۳/۱۱۲ بلفظ: ((احد)) بدل ((حراء)) ۴ - وأما حديث بريدة: فأخرجه أحمد: ۵/۳۴۶ ۵ - وأما حديث أبي هريرة: فأخرجه مسلم: ۷/۱۲۸ ، والترمذي: ۴/۳۱۹ ، وأحمد: ۲/۴۱۹ ، والخطيب: ۸/۱۶۱\n(الصحيحة: ۸۷۵)","e":"اس میں سیدنا ابو بکر صدیق اور سیدنا عمر فاروق رضی اللہ عنہما کی عظمتوں کا بیان ہے، جنھیں بالترتیب صدیق اور شہید کے القاب سے نوازا گیا۔"}],[3257,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے پوچھا: ”آج کون روزے دار ہے؟“ سیدنا ابو بکر رضی اللہ عنہ نے کہا: میں ہوں۔ آپ نے پوچھا: ”آج تم میں سے کس نے مریض کی بیمار پرسی کی ہے؟“ ابو بکر نے کہا: میں نے۔ آپ نے پوچھا: ”آج تم میں سے کس نے نماز جنازہ پڑھی ہے؟“ ابو بکر نے کہا: میں نے۔ آپ نے پوچھا: ”آج کس نے مسکین کو کھانا کھلایا ہے؟“ ابو بکر رضی اللہ عنہ نے کہا: میں نے۔ مروان کہتے ہیں کہ مجھے یہ بات پہنچی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے آخر میں فرمایا: ”جس آدمی میں ایک دن میں یہ صفات جمع ہو جائیں وہ جنت میں داخل ہوگا۔“","",{"t":"سیدنا ابو بکر صدیق رضی اللہ عنہ کی فضیلت و عظمت","k":"رواه مسلم في ”صحيحه“: ۷/۱۱۰ ، والبخاري في ”الأدب المفرد“: ۵۱۵ ، وابن خزيمة في ”صحيحه“: ۳/۳۰۴ / ۲۱۳۱ ، والبيهقي في ”السنن“: ۴/۱۸۹ ، و ”الشعب“: ۷/۵۳۷ / ۹۱۹۹ ، وابن عساكر في ”تاريخه“: ۹/۲۸۸ / ۱\n(الصحيحة: ۸۸)","e":"امام البانی رحمہ اللہ کہتے ہیں: اس حدیث میں سیدنا ابو بکر صدیق رضی اللہ عنہ کی فضیلت اور ان کے لیے جنت کی بشارت کا بیان ہے، اس موضوع پر دلالت کرنے والی کافی ساری احادیث موجود ہیں۔ نیز اس میں ایک دن میں مذکورہ بالا خصائل سے متصف ہونے کی فضیلت کا بیان ہے، جو آدمی ایک دن میں یہ نیکیاں سرانجام دے گا، اسے جنت کی بشارت دی جائے گی۔ (صحیحہ: ۸۸) خصائل یہ ہیں: ایک دن میں روزہ رکھنا، بیمار کی تیمارداری کرنا، نماز جنازہ ادا کرنا اور مسکین کو کھانا کھلانا۔"}],[3258,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ جب نبی کریم صلی اللہ علیہ وسلم کو مسجد اقصیٰ تک سیر کرائی گئی اور صبح کے وقت لوگوں نے اس موضوع پر بات چیت کرنا شروع کی تو کچھ لوگ، جو آپ صلی اللہ علیہ وسلم پر ایمان لا چکے تھے اور آپ کی تصدیق کر چکے تھے، مرتد ہو گئے، وہ سیدنا ابو بکر رضی اللہ عنہ کے پاس آئے اور کہا: یہ آپ کا ساتھی اس قسم کا دعویٰ کر رہا ہے کہ اسے آج رات بیت المقدس تک سیر کرائی گئی، اب آپ اس کے بارے میں کیا کہیں گے؟ سیدنا ابو بکر نے پوچھا: آیا آپ صلی اللہ علیہ وسلم نے یہ دعویٰ کیا ہے؟ انھوں نے کہا: جی ہاں۔ سیدنا ابو بکر نے کہا: اگر آپ صلی اللہ علیہ وسلم نے ایسی بات کی ہے تو آپ نے سچ فرمایا ہے۔ انھوں نے کہا: کیا تم تصدیق کرو گے کہ آپ راتوں رات بیت المقدس گئے اور صبح سے پہلے پہلے واپس بھی آ گئے ہیں؟ سیدنا ابو بکر صدیق نے کہا: جی ہاں، (غور کرو کہ) میں تو ان امور میں بھی آپ کی تصدیق کرتا ہوں جو (تمھاری سمجھ کے مطابق) اس (واقعہ) سے بھی مشکل اور بعید ہیں۔ میں تو صبح کے وقت آسمانی خبر یعنی آپ صلی اللہ علیہ وسلم پر نازل ہونے والی وحی کی تصدیق کرتا ہوں، وہ صبح کو موصول ہوا یا شام کو۔ اسی وجہ سے ابو بکر کو ”صدیق“ کہا گیا۔","",{"t":"سیدنا ابو بکر رضی اللہ عنہ کو صدیق کا لقب کیسے ملا؟","k":"أخرجه الحاكم: ۳/۶۲ ، ومن طريقه البيهقي في ”الدلائل“: ۲/۳۶۰ - ۳۶۱\n(الصحيحة: ۳۰۶)","e":"قربان ہو جائیں ہمارے ماں باپ ابو بکر صدیق کی صداقت پر، نبی کریم صلی اللہ علیہ وسلم کی مقدس زبان سے جو دعویٰ سنائی دیا، وہ کسی کے لیے بادی النظر میں ممکن ہو یا نہ ہو، بہرحال صدیق کے لیے قابل تسلیم ہوگا۔"}],[3259,"رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میں (خواب میں) ایک کنویں سے پانی کھینچ رہا تھا، میرے پاس ابو بکر آئے، انھوں نے ڈول پکڑا اور ایک دو ڈول کھینچے، اس کے کھینچنے میں کمزوری محسوس ہو رہی تھی اور اللہ تعالیٰ اسے بخش دے گا۔ پھر ابو بکر کے ہاتھ سے عمر بن خطاب نے (وہ ڈول) پکڑ لیا، پھر تو وہ بہت بڑا ڈول ثابت ہوا، میں نے ایسا قوی (اور باکمال) آدمی نہیں دیکھا جو اس طرح کام کرتا ہو، انھوں نے اتنا پانی کھینچا کہ لوگ اپنے اونٹوں کو سیراب کر کے پانی کے پاس ٹھہر گئے۔“ یہ حدیث سیدنا عبد اللہ بن عمر، سیدنا ابو ہریرہ اور سیدنا ابو طفیل رضی اللہ عنہم سے مروی ہے۔","",{"t":"ابو بکر صدیق رضی اللہ عنہ خلیفہ بلا فصل تھے","k":"جاء من حديث ابن عُمر، وأبي هريرة، وأبي الطفيل: (۱)۔ أما حديث ابن عُمر: فرواه البخاري: ۳۶۳۳ ، ۳۶۸۲ ، ۷۰۲۰ ، ومسلم: ۷/۱۱۳ ، والترمذي: ۲۲۷۹ ، والنسائي في ”الكبرى“: ۷۶۳۳ ، وأحمد في ”مسنده“: ۲/۷۸ و ۳۹ ، وفي ”الفضائل“: ۲۲۴ ، وابن أبي شيبة: ۱۱/۲۶ ، ۱۲/۲۱ ، والبيهقي: ۸/۱۵۴ ، وأبو يعلى: ۵۵۱۴ ، ۵۵۲۴ ، والطبراني في ”المعجم الكبير“: ۱۳۱۷۷ ، وابن أبي عاصم: ۱۴۵۶ ۲ - وأما حديث أبي هريرة: فرواه عنه جماعة: (ونحن نلخص) رواه البخاري: ۳۶۴۴ ، ۷۰۲۱ ، ۷۴۷۵ ، ومسلم: ۷/۱۱۲ ، ۱۱۳ ، وابن حبان: ۶۸۹۸ ، والنسائي في ”الكبرى“: ۸۱۱۶ ، وابن أبي عاصم: ۱۴۵۸ ، والبيهقي في ”الدلائل“: ۶/۳۴۴ ، و أحمد: ۲۱/۴۵۰ ، وابن أبي شيبة: ۱۲/۲۱ (۳) وأما حديث أبي الطفيل فرواه احمد: ۵/۴۵۵\n(الصحيحة: ۳۶۱۴)","e":"اس خواب کی تعبیر سیدنا ابو بکر صدیق رضی اللہ عنہ اور سیدنا عمر فاروق رضی اللہ عنہ کی بالترتیب خلافت ہے۔ اول الذکر کی کمزوری اور ایک دو ڈول سے مراد یہ ہے کہ وہ زیادہ دیر تک مسلمانوں کی خدمت نہ کر سکیں گے، ان کا دور ارتداد اور اختلاف و اضطراب جیسے مسائل کھڑے ہو جائیں گے اور جلدی فوت ہو جائیں گے۔ یہ ساری کم و کاست سیدنا عمر رضی اللہ عنہ نے پوری کر دی، ان کا دور خلافت تعظیم دین اور اعلائے کلمۃ اللہ کا زمانہ تھا اور شرق و غرب میں پرچم توحید لہرانے لگا۔ ”غرباً“ اس بڑے ڈول کو کہتے ہیں جو بھینس یا بیل کی کھال سے بنایا جاتا ہے، اس سے کھیتوں یا باغوں کی آبیاری کرتے ہیں۔ حدیث کے آخری جملے کا معنی یہ ہے کہ سیدنا عمر رضی اللہ عنہ کی خلافت میں اسلام پھیلے گا اور فتوحات اتنی بے شمار ہوں گی کہ لوگ مال و دولت سے سیراب ہو جائیں گے۔"}],[3260,"سیدہ عائشہ رضی اللہ عنہا کہتی ہیں: جب رسول اللہ صلی اللہ علیہ وسلم کی بیماری بڑھ گئی تو (میرے بھائی) عبد الرحمن بن ابو بکر کو حکم دیا کہ ”کوئی تختی یا ہڈی لاؤ، میں ابو بکر کے حق میں کچھ لکھنا چاہتا ہوں تاکہ اس پر کسی کو اختلاف نہ ہو۔“ جب عبد الرحمن چلا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: ”ابو بکر! اللہ تعالیٰ نے اور مومنوں نے اس بات سے انکار کر دیا ہے کہ تجھ پر اختلاف کیا جائے۔“","",{"t":"ابو بکر صدیق رضی اللہ عنہ خلیفہ بلا فصل تھے","k":"أخرجه أحمد: ۶/۴۷ ، والحسن بن عرفة في ”جزئه“: ۲/۲ ، ومن طريقه ابن بلبان في ”تحفة الصديق في فضائل أبي بكر الصديق“: ۱/۵۰ واخرجه البخاري: ۴/۴۶ ، ۴۰۵ ، ومسلم: ۷/۱۱۰ ، واحمد: ۶/۱۴۴\n(الصحيحة: ۶۹۰)","e":"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ان کو اپنی بیماری کے دوران کہا: (اُدْعِي لِي أَبَابَكْرٍ أَبَاكَ وَأَخَاكَ حَتَّى أَكْتُبَ كِتَابًا، فَإِنِّي أَخَافُ أَنْ يَتَمَنَّى مُتَمَنٍّ وَيَقُولَ قَائِلٌ: أَنَا أَوْلَى، وَيَأْبَى اللهُ وَالْمُؤْمِنُونَ إِلَّا أَبَا بَكْرٍ - (مسلم) ..... ”اپنے باپ ابو بکر اور بھائی کو بلاؤ، تاکہ میں کچھ لکھ ہی دوں، کیونکہ مجھے خدشہ کہ کوئی خواہش مند تمنا کر سکتا ہے اور کوئی کہہ سکتا ہے کہ وہ (خلافت کا) زیادہ حقدار ہے۔ لیکن اللہ تعالیٰ اور مومنین تو ابو بکر کے علاوہ ہر کسی کا انکار کرتے ہیں۔“ سیدنا عبد اللہ بن زمعہ رضی اللہ عنہ کہتے ہیں: آپ صلی اللہ علیہ وسلم کی بیماری شدت اختیار کر گئی، میں بھی کچھ مسلمانوں سمیت آپ صلی اللہ علیہ وسلم کے پاس موجود تھا، سیدنا بلال نے آپ صلی اللہ علیہ وسلم کو نماز کے لیے بلایا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”کسی کو حکم دے دو کہ وہ نماز پڑھا دے۔“ جب میں باہر آیا تو دیکھا کہ لوگوں میں عمر رضی اللہ عنہ بیٹھے تھے اور ابو بکر صدیق رضی اللہ عنہ غائب تھے۔ میں نے کہا: عمر! اٹھو اور لوگوں کو نماز پڑھاؤ۔ پس وہ آگے بڑھے اور تکبیر تحریمہ کہی، چونکہ وہ بلند آواز والے تھے، اس لیے آپ صلی اللہ علیہ وسلم نے ان کی آواز سن لی اور پوچھا: ”ابو بکر کہاں ہیں؟ اللہ اور مسلمان کسی اور کے آگے بڑھنے کا انکار کرتے ہیں، اللہ اور مسلمان کسی اور کے آگے بڑھنے کا انکار کرتے ہیں۔“ پھر ابو بکر کی طرف پیغام بھیجا، وہ تشریف لے آئے، لیکن اس وقت سیدنا عمر رضی اللہ عنہ وہ نماز پڑھا چکے تھے۔ (ابو داود: ۴۶۶۰ ، احمد: ۱۸۴۲۷) یہ روایات اس بات کا قطعی ثبوت ہیں کہ آپ صلی اللہ علیہ وسلم کے خلیفہ اول سیدنا ابو بکر صدیق رضی اللہ عنہ ہی ہیں اور عملاً ایسے ہی ہوا کہ آپ صلی اللہ علیہ وسلم کی وفات کے بعد سقیفہ بنی ساعدہ میں سیدنا عمر رضی اللہ عنہ، ارباب حل و عقد اور پھر تمام مسلمانوں نے سیدنا ابو بکر رضی اللہ عنہ کی بیعت کی۔ جو سیدنا ابو بکر رضی اللہ عنہ کی خلافت کا بین ثبوت ہے۔ اگر سیدنا ابو بکر رضی اللہ عنہ کی خلافت کسی شرعی دلیل سے ثابت نہ بھی ہوتی تو ان کی خلافت کے برحق ہونے کے لیے صحابہ کرام کا اجماع و اتفاق ہی کافی تھا۔"}],[3261,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے، نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”اے اللہ! عمر بن خطاب کے ذریعے اسلام کو غلبہ نصیب فرما۔“","",{"t":"سیدنا عمر فاروق رضی اللہ عنہ کے فضائل و مناقب","k":"أخرجه ابن حبان في ”صحيحه“: ۲۱۸۰ - موارد من طريق عبدالله بن عيسى الفروي، وكذا البيهقي في ”سننه“: ۶/۳۷۰ ، وابن عدي في ”الكامل“: ۶/۳۱۰ ، وعنه ابن عساكر في ”تاريخ الدمشق“: ۱۲/۷۱۸ ، والحاكم: ۳/۸۳ ، وعنه البيهقي\n(الصحيحة: ۳۲۲۵)","e":"اللہ تعالیٰ نے اس دعائے نبوی کی قدر کی اور سیدنا عمر بن خطاب رضی اللہ عنہ کے ذریعے اسلام کو اقتدار عطا کیا۔ سیدنا عمر بن خطاب رضی اللہ عنہ کی عظمت اور حق گوئی کا منہ بولتا ثبوت ہے کہ ان کو غلبہ اسلام کے لیے مانگا گیا تھا۔"}],[3262,"سیدنا عقبہ بن عامر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اگر میرے بعد کوئی نبی ہوتا تو وہ عمر (رضی اللہ عنہ) ہوتا۔“","",{"t":"سیدنا عمر فاروق رضی اللہ عنہ کے فضائل و مناقب","k":"رواه الترمذي: ۲/۲۹۳ وحسنه، والحاكم: ۳/۸۵ وصححه، وأحمد: ۴/۱۵۴ ، والروياني في ”مسنده“: ۱/۵۰ ، والطبراني في ”الكبير“: ۱۷/۲۵۷ ، وأبوبكر النجاد في ”الفوائد المنتقاة“: ۱۷/۷۰ - ۱ ، وابن سمعون في ”الأمالي“: ۲/۱۷۷ ، وأبوبكر القطيعي في ”الفوائد المنتقاة“: ۴/۷ / ۲ ، والخطيب في ”الموضح“: ۲/۲۲۲ ، وابن عساكر: ۳/۲۱۰ / ۲\n(الصحيحة: ۳۲۷)","e":"اس میں سیدنا عمر رضی اللہ عنہ کی صلاحیت، لیاقت، قابلیت، اہلیت، حق گوئی اور حق کے قریب ہونے کی نشاندہی کی گئی ہے۔"}],[3263,"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میں نے خواب میں دیکھا کہ میں جنت میں داخل ہوا، اچانک میری نگاہ ابو طلحہ کی بیوی رمیصا پر پڑی اور مجھے اپنے سامنے والی جانب سے کسی کے حرکت کرنے کی آواز سنائی دی۔ میں نے کہا: جبریل! یہ کون ہے؟ اس نے کہا: یہ بلال ہے۔ پھر میں نے ایک سفید محل دیکھا، اس کے صحن میں ایک لڑکی بھی موجود تھی۔ میں نے پوچھا: یہ کس کا محل ہے؟ اس نے جواب دیا: یہ عمر بن خطاب کا ہے۔ میں نے چاہا کہ اس میں داخل ہو جاؤں اور (اندر سے) دیکھ لوں، لیکن عمر! مجھے تیری غیرت یاد آ گئی۔“ سیدنا عمر رضی اللہ عنہ نے کہا: اے اللہ کے رسول! میرے ماں باپ آپ پر قربان ہوں، کیا میں آپ پر غیرت کر سکتا ہوں؟","",{"t":"سیدنا عمر فاروق رضی اللہ عنہ کے فضائل و مناقب","k":"أخرجه البخاري: ۲/۴۲۵ ، والطيالسي في ”مسنده“: ۱۷۱۹ ، وأحمد: ۳/۳۷۲ ، ۳۸۹\n(الصحيحة: ۱۴۰۵)"}],[3264,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میں جنت میں داخل ہوا، اچانک سونے کا ایک محل دیکھا۔ میں نے پوچھا: یہ محل کس کا ہے؟ انھوں نے کہا: ایک قریشی جوان کا ہے۔ مجھے خیال تھا کہ یہ میرا ہی ہوگا (کیونکہ میں قریشی ہوں)۔ بہرحال میں نے پوچھا: وہ قریشی کون ہے؟ انھوں نے کہا: یہ عمر بن خطاب رضی اللہ عنہ کا ہے۔“ پھر آپ نے فرمایا: ”عمر! اگر تیری غیرت و حمیت کا مسئلہ نہ ہوتا تو میں اس میں ضرور داخل ہو جاتا۔“ سیدنا عمر رضی اللہ عنہ نے کہا: اے اللہ کے رسول! کیا میں آپ پر غیرت کھا سکتا ہوں؟“","",{"t":"سیدنا عمر فاروق رضی اللہ عنہ کے فضائل و مناقب","k":"أخرجه الترمذي: ۲/۲۹۳ ، وابن حبان: ۲۱۸۸ ، وأحمد: ۳/۱۰۷ و۱۷۹\n(الصحيحة: ۱۴۲۳)","e":"آپ صلی اللہ علیہ وسلم نے سیدنا عمر رضی اللہ عنہ کی غیرت، شدت اور حدّت کا خیال رکھا، جب کہ ان کے جواب کا یہ مقصد تھا کہ اللہ تعالیٰ نے ان کو آپ کی وجہ سے رفعت عطا کی ہے اور آپ کے ذریعے ہدایت سے نوازا ہے، بھلا وہ آپ پر کیسے غیرت کر سکتے ہیں۔"}],[3265,"ابو امامہ بن سہل بن حنیف ایک صحابی رسول سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”میں سو رہا تھا، اچانک کیا دیکھتا ہوں کہ لوگ مجھ پر اس حال میں پیش کیے جانے لگے کہ انھوں نے قمیصیں پہنی ہوئی تھیں، کسی کی قمیص سینے تک تھی، کسی کی اس سے نیچے تک، اتنے میں عمر کو پیش کیا گیا، ان کی قمیص تو (اتنی لمبی تھی کہ) گھسٹ رہی تھی۔“ صحابہ نے پوچھا: اے اللہ کے رسول! اس خواب کی تعبیر کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”(قمیصوں سے مراد) دین ہے۔“","",{"t":"سیدنا عمر فاروق رضی اللہ عنہ کے فضائل و مناقب","k":"رواه عبدالرزاق: ۲۰۳۸۵ ، ومن طريقه: أحمد: ۵/۳۷۳ ، والترمذي: ۲۲۸۵ ، وأخرجه البخاري: ۲۳ ، ۲۳۹۰ ، ومسلم: ۷/۱۱۲ ، والترمذي: ۲۲۸۶ وغيرهم لكن سمّوا الصحابي المبهم: أبا سعيد الخدري\n(الصحيحة: ۳۶۱۲)","e":"سیدنا عمر رضی اللہ عنہ نبوی شہادت کے مطابق دین اسلام سے مکمل طور پر مزین تھے۔ مفہوم یہ ہوا کہ سیدنا عمر رضی اللہ عنہ کی خلافت کا دورانیہ طویل ہوگا، اس میں دین کو سر بلندی نصیب ہوگی، ان کی حیات میں اور موت کے بعد ان کی فتوحات کے آثار باقی رہیں گے۔ قمیص کے گھسٹنے کا معنی یہ ہوا کہ ان کی وفات کے بعد ان کے آثار جمیلہ اور سنن حسنہ مسلمانوں میں باقی رہیں گی۔ (تلخیص از مرقاة المفاتيح: ۱/۳۹۳)"}],[3266,"رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ابو بکر اور عمر پہلے اور پچھلے لوگوں میں سے جنت میں داخل ہونے والے عمر رسیدہ لوگوں کے سردار ہیں۔“ یہ حدیث سیدنا علی بن ابو طالب، سیدنا انس بن مالک، سیدنا ابو جحیفہ، سیدنا جابر بن عبد اللہ اور سیدنا ابو سعید خدری رضی اللہ عنہم سے مروی ہے۔","",{"t":"سیدنا عمر فاروق رضی اللہ عنہ کے فضائل و مناقب","k":"۱- أما حديث علي؛ فأخرجه الترمذي: ۴/۳۱۰ ، وابن ماجه: ۱/۴۹ ، وابن عدي: ۲/۲۱۴ ، وابن شاهين في ”السنة“: ۶۷ - نسختي، والخطيب في ”تاريخ بغداد“: ۱۰/۱۹۲ ، وابن عساكر في ”تاريخ دمشق“: ۹/۳۰۷ / ۲ ، والدولابي في ”الكنى“: ۲/۹۹ ، وابن عدي: ۲/۱۰۰ ، وعبد الغني المقدسي في ”الاكمال“: ۱/۱۴ / ۲ ، وابن عساكر: ۹/۳۱۰ / ۱ ، وعبدالله بن أحمد في ”زوائد المسند“: ۱/۸۰ ۲- وأما حديث أنس؛ فأخرجه الترمذي: ۴/۳۱۰ ، والضياء المقدسي في ”المختارة“: ۱۹۷ - ۱۹۸ ، وابن عساكر: ۲/۱۲۵۰ / ۱ ، ۹/۳۱۰ / ۱ ، ۱۳/۲۴ / ۱ ، وابن عساكر: ۹/۳۱۰ / ۲ ، والضياء: ۲/۱۴۵ ۳- وأما حديث أبو جحيفة عن أبيه؛ فأخرجه ابن حبان: ۲۱۹۲ ، وكذا ابن ماجه: ۱/۵۱ ، والدولابي في ”الكنى“: ۱/۱۲۰ ۴- وأما حديث جابر؛ فرواه الطبراني في ”الأوسط“، قال الهيثمي: ۹/۵۳ ، ومن هذا الوجه أخرجه ابن عساكر: ۱۳/۲۴ / ۱ ۵- وأما حديث أبي سعيد؛ فرواه الطبراني في ”الأوسط“ ۶- أما حديث ابن عمر؛ فأخرجه السهمي في ”تاريخ جرجان“: ۷۷ ، وابن عساكر: ۱۳/۲۳ / ۲ ، وقال ابن أبي حاتم: ۲/۳۸۹\n(الصحيحة: ۸۲۴)","e":"صدیق و فاروق ان لوگوں کے سردار ہوں گے، جو لوگ ادھیڑ عمری میں فوت ہو کر جنت میں داخل ہوتے ہیں، وگرنہ جنت میں تو سب جنتیوں کی عمریں، جوانیاں اور قد و قامت وغیرہ برابر ہوں گے۔ ہم نے حدیث کے لفظ ”كُهُول“ کا معنی ادھیڑ عمر والے لوگ کیا ہے، جبکہ قاموس میں ہے کہ تیس یا پینتیس برس سے لے کر اکاون برس تک کی عمر والوں کو ”كُهُول“ کہتے ہیں۔ امام ترمذی نے اپنے باب میں واضح کیا ہے کہ صدیق و فاروق جن لوگوں کے سردار ہوں گے، ان میں انبیا و رسل داخل نہیں ہیں۔"}],[3267,"سیدنا عبداللہ بن حنطب رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے سیدنا ابو بکر اور سیدنا عمر رضی اللہ عنہما کو دیکھ کر فرمایا: ”یہ (میری امت کے) کان اور آنکھیں ہیں۔“","",{"t":"سیدنا عمر فاروق رضی اللہ عنہ کے فضائل و مناقب","k":"أخرجه الترمذي: ۴/۳۱۱\n(الصحيحة: ۸۱۴)","e":"یعنی سر میں جو اہمیت کان اور آنکھ کی ہے وہ مدینہ اسلام میں صدیق و فاروق کی ہے، کانوں اور آنکھوں کے بغیر انسان کیسا لگتا ہے؟ اس کی کتنی وقعت ہوتی ہے؟ وہ اپنی صلاحیتوں سے کس قدر مستفید ہو سکتا ہے؟ یہی حشر اس اسلام کا ہوگا، جس میں رسول اللہ صلی اللہ علیہ وسلم کے سر صدیق و فاروق نہیں ہوں گے۔"}],[3268,"عبد اللہ بن بریدہ اپنے باپ سے روایت کرتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم ایک غزوے سے واپس آئے تو سیاہ رنگ کی ایک لونڈی آپ صلی اللہ علیہ وسلم کے پاس آئی اور کہا: میں نے نذر مانی تھی کہ اگر اللہ تعالیٰ نے آپ کو فاتح لوٹایا تو میں آپ کے پاس دف بجاؤں گی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اگر نذر مانی ہے تو ٹھیک ہے (دف بجا لے)، وگرنہ نہیں۔“ اس نے دف بجانا شروع کیا، ابو بکر رضی اللہ عنہ آئے، وہ بجاتی رہی، دوسرے صحابہ آئے، وہ اسی حالت پر رہی۔ لیکن جب سیدنا عمر رضی اللہ عنہ آئے تو اس نے دف چھپانے کے لیے اسے اپنے نیچے رکھ دیا اور دوپٹہ اوڑھ لیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”عمر! شیطان تجھ سے ڈرتا ہے۔ میں اور یہ لوگ یہاں بیٹھے تھے (یہ دف بجاتی رہی) لیکن جب تم داخل ہوئے تو اس نے ایسے ایسے کر دیا۔“","",{"t":"سیدنا عمر فاروق رضی اللہ عنہ کے فضائل و مناقب","k":"أخرجه أحمد: ۵/۳۵۳ ، والترمذي: ۴/۳۱۶ ، وابن حبان: ۲۱۸۶\n(الصحيحة: ۱۶۰۹)","e":"اگرچہ اس موقع پر اس لونڈی کا دف بجانا جائز تھا، تھی تو نبی کریم صلی اللہ علیہ وسلم نے اجازت دی۔ یہ سیدنا عمر رضی اللہ عنہ کا رعب اور ہیبت تھی، جس کا رسول اللہ صلی اللہ علیہ وسلم بھی لحاظ کرتے تھے۔ امام البانی رحمہ اللہ نے کہا: اس حدیث کی وجہ سے بعض لوگ اشکال میں پڑ گئے ہیں اور وہ یہ کہ نکاح اور عید کے علاوہ دف بجانا معصیت اور نافرمانی کا کام ہے اور نافرمانی پر مشتمل نذر ماننا بھی ناجائز ہے اور اس کو پورا کرنا بھی ناجائز ہے، لیکن اس موقع پر اجازت کیوں دی گئی؟ مجھے تو یہ معلوم ہوتا ہے کہ اس عورت کی نذر کا تعلق اس خوشی سے تھا، جو غزوے سے نبی کریم صلی اللہ علیہ وسلم کے فاتح لوٹنے سے نصیب ہوئی تھی، اس لیے اسے اس خوشی کے موقع پر دف بجانے کی اجازت دے دی گئی، لیکن یہ چیز آپ صلی اللہ علیہ وسلم کی فتح کے ساتھ مخصوص رہنی چاہیے، اس گنجائش کا مطلب یہ نہیں کہ تمام خوشیوں کے موقعوں پر دف بجانے کی رخصت دے دی جائے، کیونکہ کوئی خوشی بھی آپ صلی اللہ علیہ وسلم کے فاتح لوٹنے کی خوشی کا مقابلہ نہیں کر سکتی۔ دوسری بات یہ ہے یہ عام شرعی دلائل سے معلوم ہوتا ہے کہ موسیقی کے آلات اور دف وغیرہ کا استعمال حرام ہے، مگر وہ صورتیں جن میں دف کی اجازت دی گئی۔ (صحیحہ: ۱۶۰۹) امام البانی رحمہ اللہ نے دوسرے مقام پر فرمایا: یہ بات تو معروف ہے کہ دُف، موسیقی اور ساز کے ان آلات میں سے ہے، جو شریعت اسلامیہ میں حرام ہیں اور فقہاے اربعہ سمیت بڑے بڑے ائمہ اس کی حرمت پر متفق ہیں، اس موضوع پر صحیح احادیث پائی جاتی ہیں، البتہ شادی بیاہ اور عیدین کے موقع پر صرف دف بجانے کی اجازت دی گئی ہے، سوال یہ پیدا ہوتا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اس عورت کو دف بجانے کی نذر پوری کرنے کی اجازت کیوں دی، حالانکہ اللہ تعالیٰ کی نافرمانی میں مانی گئی نذر پوری نہیں کی جاتی؟ اس کا جواب یہ ہے کہ اس نذر کا تعلق اس خوشی سے تھا، جو اس کو نبی کریم صلی اللہ علیہ وسلم کے فاتح اور سالم لوٹنے سے نصیب ہوئی تھی، اس لیے آپ صلی اللہ علیہ وسلم نے اس کو شادی اور عیدین کے موقع پر بجائے جانے والے دف کا حکم دیا، اور بلاشبہ آپ صلی اللہ علیہ وسلم کا غزوہ سے کامیابی و کامرانی کے ساتھ لوٹنے کی خوشی اتنی بڑی ہے کہ اس کو شادی اور عید کی خوشی پر بھی قیاس نہیں کیا جا سکتا، اس لیے اس حکم کو آپ صلی اللہ علیہ وسلم کے ساتھ خاص سمجھا جائے گا اور کسی دوسرے کے معاملے کو اس پر قیاس نہیں کیا جائے گا، کیونکہ یہ لوہاروں کو فرشتوں پر قیاس کرنے والی بات ہوگی۔ امام خطابی نے (معالم السنن) میں اور علامہ صدیق حسن خان نے (الروضة الندية: ۲/۱۷۷ - ۱۷۸) میں جمع و تطبیق کی یہی صورت ذکر کی۔ (صحیحہ: ۲۲۶۱)"}],[3269,"رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میں (خواب میں) ایک کنویں سے پانی کھینچ رہا تھا، میرے پاس ابو بکر آئے، انھوں نے ڈول پکڑا اور ایک دو ڈول کھینچے، اس کے کھینچنے میں کمزوری محسوس ہو رہی تھی اور اللہ تعالیٰ اسے بخش دے گا۔ پھر ابو بکر کے ہاتھ سے عمر ابن خطاب نے (وہ ڈول) پکڑ لیا، پھر تو وہ بہت بڑا ڈول ثابت ہوا، میں نے ایسا قوی (اور باکمال) آدمی نہیں دیکھا جو اس طرح کام کرتا ہو، انھوں نے اتنا پانی کھینچا کہ لوگ اپنے اونٹوں کو سیراب کر کے پانی کے پاس ٹھہر گئے۔“ یہ حدیث سیدنا عبد اللہ بن عمر، سیدنا ابو ہریرہ اور سیدنا ابو طفیل رضی اللہ عنہم سے مروی ہے۔","",{"t":"سیدنا عمر فاروق رضی اللہ عنہ کے فضائل و مناقب","k":"جاء من حديث ابن عُمر، وأبي هريرة، وأبي الطفيل: (۱) - أما حديث ابن عُمر؛ فرواه البخاري: ۳۶۳۳ ، ۳۶۸۲ ، ۷۰۲۰ ، ومسلم: ۷/۱۱۳ ، والترمذي: ۲۲۷۹ ، والنسائي في ”الكبرى“: ۷۶۳۶ ، وأحمد في ”مسنده“: ۲/۲۸ و۳۹ ، وفي ”الفضائل“: ۴۲۴ ، وابن أبي شيبة: ۱۱/۶۲ ، ۱۲/۲۱ ، والبيهقي: ۸/۱۵۴ ، وأبويعلى: ۵۵۱۴ ، ۵۵۲۴ ، والطبراني في ”المعجم الكبير“: ۱۳۱۷۷ ، وابن أبي عاصم: ۱۴۵۶ ۲- وأما حديث أبي هريرة؛ فرواه عنه جماعة: (ونحن نلخص) رواه البخاري: ۳۶۴۴ ، ۷۰۲۱ ، ۷۴۷۵ ، ومسلم: ۷/۱۱۲ ، ۱۱۳ ، وابن حبان: ۶۸۹۸ ، والنسائي في ”الكبرى“: ۸۱۱۶ ، وابن أبي عاصم: ۱۴۵۸ ، والبيهقي في ”الدلائل“: ۶/۳۴۴ ، وأحمد: ۲۱/۴۵۰ ، وابن أبي شيبة: ۱۲/۲۱ (۳) وأما حديث أبي الطفيل فرواه أحمد: ۵/۴۵۵\n(الصحيحة: ۳۶۱۴)","e":"اس خواب کی تعبیر سیدنا ابو بکر صدیق رضی اللہ عنہ اور سیدنا عمر فاروق رضی اللہ عنہ کی بالترتیب خلافت ہے۔ اول الذکر کی کمزوری اور ایک دو ڈول سے مراد یہ ہے کہ وہ زیادہ دیر تک مسلمانوں کی خدمت نہ کر سکیں گے، انکار و ارتداد اور اختلاف و اضطراب جیسے مسائل کھڑے ہو جائیں گے اور جلدی فوت ہو جائیں گے۔ یہ ساری کم و کاست سیدنا عمر رضی اللہ عنہ نے پوری کر دی، ان کا دور خلافت تعظیم دین اور اعلائے کلمۃ اللہ کا زمانہ تھا اور شرق و غرب میں پرچم توحید لہرانے لگا۔ ”غَرْبًا“ اس بڑے ڈول کو کہتے ہیں جو بھینس یا بیل کی کھال سے بنایا جاتا ہے، اس سے کھیتوں یا باغوں کی آبیاری کرتے ہیں۔ حدیث کے آخری جملے کا معنی یہ ہے کہ سیدنا عمر رضی اللہ عنہ کی خلافت میں اسلام پھیلے گا اور فتوحات اتنی بے شمار ہوں گی کہ لوگ مال و دولت سے سیراب ہو جائیں گے۔"}],[3270,"سیدہ ام سلمہ رضی اللہ عنہا کہتی ہیں کہ میرے پاس عبد الرحمن بن عوف رضی اللہ عنہ آئے اور کہا: امی جان! میں قریش کا امیر ترین آدمی ہوں، مجھے ڈر لگ رہا ہے کہ کہیں یہ کثرت مال مجھے ہلاک نہ کر دے۔ انھوں نے کہا: میرے بیٹے! خرچ کیا کرو، کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”میرے بعض صحابہ ایسے بھی ہیں جو میری مفارقت کے بعد مجھے نہیں ملیں گے۔“ وہ وہاں سے نکل پڑے، سیدنا عمر رضی اللہ عنہ کو ملے، (اور انھیں یہ حدیث سنائی)۔ سیدنا عمر، سیدہ ام سلمہ کے پاس آئے اور کہا: اللہ کی قسم! کیا میں بھی ان میں سے ہوں؟ انھوں نے کہا: نہیں۔ لیکن آپ کے بعد کسی کو خبر نہیں دوں گی۔","",{"t":"سیدنا عمر فاروق رضی اللہ عنہ کے فضائل و مناقب","k":"أخرجه أحمد: ۶/۲۹۰ ، والبزار: ۳/۱۷۲ / ۲۴۹۶ ، والطبراني في ”المعجم الكبير“: ۲۳/۳۱۹ / ۷۷۴ ، ۳۹۴ / ۹۴۱\n(الصحيحة: ۲۹۸۲)"}],[3271,"سیدنا عبد اللہ بن عباس رضی اللہ عنہما کہتے ہیں: میں نے سیدنا عمر بن خطاب رضی اللہ عنہ کو کہتے ہوئے سنا کہ جب عبد اللہ بن ابی (منافق) مرا تو رسول اللہ صلی اللہ علیہ وسلم کو اس کی نماز جنازہ کے لیے بلایا گیا، آپ صلی اللہ علیہ وسلم تشریف لے گئے اور جب نماز کے ارادے سے کھڑے ہوئے تو میں گھوم کر آپ صلی اللہ علیہ وسلم کے سامنے کھڑا ہو گیا اور کہا: اے اللہ کے رسول! کیا اللہ تعالیٰ کے دشمن عبد اللہ بن ابی کی نماز جنازہ (پڑھنے لگے ہو)، جس نے فلاں فلاں دن ایسے ایسے کہا تھا؟ ان دنوں کو شمار بھی کیا، آپ صلی اللہ علیہ وسلم جواباً مسکرا دیے۔ جب میں نے بہت زیادہ اصرار کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: ”عمر! پیچھے ہٹ جاؤ، مجھے اختیار دیا گیا اور میں نے (اس اختیار کو) قبول کر لیا، مجھے (اللہ تعالیٰ کی طرف سے) کہا گیا ہے: ﴿اے محمد! آپ ان کے لیے بخشش طلب کریں یا نہ کریں، اگر آپ ستر دفعہ بھی بخشش طلب کریں تو پھر بھی اللہ تعالیٰ ان کو ہرگز معاف نہیں کرے گا﴾ (سورہ توبہ: ۸۰) اگر مجھے علم ہوتا کہ ستر سے زائد دفعہ بخشش طلب کرنے سے اسے بخش دیا جائے گا تو میں زیادہ دفعہ کر دیتا۔“ پھر آپ صلی اللہ علیہ وسلم نے نماز پڑھائی، اس کی میت کے ساتھ چلے اور فارغ ہونے تک اس کی قبر پر کھڑے رہے۔ مجھے رسول اللہ صلی اللہ علیہ وسلم پر جرأت کرنے پر بڑا تعجب ہو رہا تھا، اللہ اور اس کا رسول ہی بہتر جانتے ہیں۔ اللہ کی قسم! تھوڑے وقت کے بعد ہی یہ دو آیات نازل ہوئیں: ﴿اے محمد! منافقوں میں سے جو بھی مرے، آپ نہ کبھی اس کی نماز جنازہ پڑھائیں اور نہ اس کی قبر پر کھڑے ہوں، انھوں نے اللہ اور اس کے رسول کے ساتھ کفر کیا ہے اور فسق کی حالت میں مرے ہیں۔﴾ (سورہ توبہ: ۸۴) (ان آیات کے نزول کے بعد) آپ صلی اللہ علیہ وسلم نے نہ کسی منافق کی نماز جنازہ پڑھی اور نہ اس کی قبر پر کھڑے ہوئے، یہاں تک کہ فوت ہو گئے۔","",{"t":"سیدنا عمر فاروق رضی اللہ عنہ کے فضائل و مناقب","k":"أخرجه الترمذي: ۲/۱۸۵ ، وأحمد: ۱/۱۶ ، واخرجه البخاري: ۱/۳۴۳ ، ۳/۷۵۳ ، دون قوله: ((وقد قيل لي: استغفر لهم ....)) وقوله: ((فما صلى بعده لى منافق ....)) وهكذا رواه النسائي: ۱/۲۷۹\n(الصحيحة: ۱۱۱۳)","e":"نبی کریم صلی اللہ علیہ وسلم رحمۃ للعالمین تھے، اپنے دشمنوں کے حسن عاقبت کے بھی حریص تھے۔ بہرحال بعد میں معلوم ہوا کہ سیدنا عمر رضی اللہ عنہ کا مشورہ زیادہ درست تھا۔ درست تھا معلوم ہوا کہ کوئی مسلمان مشرک کی نماز جنازہ نہیں پڑھ سکتا، آج کل جو لوگ برادریوں کا پاس و لحاظ کرتے ہوئے ایسا کرتے ہیں، انھیں چاہیے کہ وہ اللہ تعالیٰ کے قرآن کو سامنے رکھیں کہ جس کی ہدایات پر عمل کرتے ہوئے آپ صلی اللہ علیہ وسلم نے نہ مذکورہ بالا واقعہ کے بعد کسی مشرک کی نماز جنازہ پڑھی اور نہ کسی ایسے فرد کی قبر پر کھڑے ہوئے۔"}],[3272,"رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میرے بعد ابو بکر اور عمر کی پیروی کرنا، عمار کی سیرت اختیار کرنا اور ابن مسعود کے عہد کو تھام لینا۔“ یہ حدیث سیدنا عبد اللہ بن مسعود، سیدنا حذیفہ بن یمان، سیدنا انس بن مالک اور سیدنا عبد اللہ بن عمر رضی اللہ عنہم سے روایت کی گئی ہے۔","",{"t":"سیدنا عمر فاروق رضی اللہ عنہ کے فضائل و مناقب","k":"۱ - أما حديث ابن مسعود: فأخرجه الترمذي: ۲/۳۱۱ ، والحاكم: ۳/۷۵ ۲- وأما حديث حذيفة: أخرجه الترمذي: ۲/۲۹۰ ، والطحاوي في ”المشكل“: ۲/۸۳ - ۸۴ ، وأحمد: ۵/۳۸۵ ، ۴۰۲ ، والحميدي في ”مسنده“: ۱/۲۱۴ / ۲۴۹ ، وابن سعد: ۲/۳۳۴ ، وابن أبي عاصم في ”السنة“: ۱۰۴۸ و۱۰۴۹ - بتحقيقي، وأبو نعيم في ”الحلية“: ۹/۱۰۹ ، والخطيب: ۱۲/۷۰ ، والحاكم: ۳/۷۵ ، وابن عساكر: ۹/۳۲۳ / او ۱۲/۳۱ / ۱ مختصرا او مطولا، وبعضم ذكر المولى، وبعضم لم يذكره، وهو الذي رجحه الحاكم خلافا لأبي حاتم في: العلل“ ۲/۳۸۱ ۳- وأما حديث أنس بن مالك: فأخرجه ابن عدي: ۱/۷۵ ۴- وأما حديث ابن عمر: فأخرجه ابن عساكر: ۹/۳۲۳ / ۲\n(الصحيحة: ۱۲۳۳)","e":"دوسری احادیث کی روشنی میں یہ کہنا درست ہے کہ خلفائے راشدین اور صحابہ کرام کی اطاعت کی جائے گی، جب تک اللہ تعالیٰ اور رسول اللہ صلی اللہ علیہ وسلم کی نافرمانی نہ ہو۔"}],[3273,"محمد بن سعد اپنے باپ سے روایت کرتے ہیں کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم کے پاس آنے کی اجازت طلب کی، اس وقت آپ کے پاس قریشی عورتیں بیٹھی تھیں، وہ آپ سے سوال کر رہی تھیں، کثرت کا مطالبہ کر رہی تھیں اور بلند آواز میں (اپنے مطالبات کا) اظہار کر رہی تھیں۔ جب سیدنا عمر نے اندر آنے کی اجازت لی تو انھوں نے جلدی جلدی پردہ کر لیا۔ نبی کریم صلی اللہ علیہ وسلم نے سیدنا عمر کو اجازت دی، جب وہ داخل ہوئے تو آپ صلی اللہ علیہ وسلم ہنس رہے تھے۔ انھوں نے کہا: اے اللہ کے رسول! میرے ماں باپ آپ پر قربان ہوں اور اللہ تعالیٰ آپ کو ہنساتا رہے (بھلا مسکرانے کی وجہ کیا ہے)؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”مجھے ان عورتوں پر بڑا تعجب ہو رہا ہے، یہ میرے پاس بیٹھی تھیں، جب انھوں نے تمھاری آواز سنی تو جلدی جلدی پردہ کر لیا۔“ انھوں نے کہا: اے اللہ کے رسول! آپ اس بات کے زیادہ مستحق ہیں کہ آپ سے ڈرا جائے۔ پھر وہ ان عورتوں پر متوجہ ہوئے اور کہا: اپنے نفسوں کی دشمنو! کیا تم مجھ سے ڈرتی ہو اور رسول اللہ صلی اللہ علیہ وسلم سے نہیں ڈرتی؟ انھوں نے کہا: تم رسول اللہ کی بہ نسبت زیادہ سخت رو ہو۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اے ابن خطاب! بس کرو، اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! جب شیطان تجھے کسی گلی میں چلتے دیکھتا ہے تو وہ (تجھ سے خوفزدہ ہو کر) دوسری گلی میں چلا جاتا ہے۔“","",{"t":"سیدنا عمر فاروق رضی اللہ عنہ کے فضائل و مناقب","k":"رواه البخاري: ۳۲۹۴ ، ۳۶۸۳ ، ۶۰۸۵ ، ومسلم: ۷/۱۱۴ - ۱۱۵ ، والنسائي في ”السنن الكبرى“: (۸۱۳۰ - فضائل الصحابة) و (۵۰۳۵ - عمل اليوم والليلة)، وابن حبان في ”صحيحه“: ۶۸۹۳ - ”الأحسان“، وابن أبي شيبة: ۱۴/۸۳ ، وأحمد في ”مسنده“: ۱/۱۷۱\n(الصحيحة: ۳۶۰۳)","e":"اس کا مطلب یہ نہیں کہ نبی کریم صلی اللہ علیہ وسلم کی مجلس میں عورتیں کوئی گناہ والا کام کر رہی تھیں۔ درحقیقت سیدنا عمر رضی اللہ عنہ کی شخصیت میں ہیبت اور رعب تھا، آپ صلی اللہ علیہ وسلم بھی ان کے اس وصف کا خیال رکھتے تھے۔ اس میں سیدنا عمر رضی اللہ عنہ کی عظیم منقبت کا بیان ہے۔ وہ دین میں اس قدر سخت اور خالص حق پر ڈٹ جانے والے تھے کہ شیطان ان کے سامنے آنے کی جرأت نہیں کر سکتا تھا۔"}],[3274,"سیدنا جابر بن عبد اللہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”دین اسلام میں ابو بکر اور عمر کی اہمیت سر میں کان اور آنکھ کی سی ہے۔“","",{"t":"سیدنا عمر فاروق رضی اللہ عنہ کے فضائل و مناقب","k":"أخرجه الطبراني والخطيب في ”تاريخ بغداد“: ۸/۴۵۹ ، وابن شاهين في ”فضائل العشرة المبشرين بالجنة“ من ”السنة“ له رقم: ۷۰ نسختي، والطبراني، وابو نعيم في ”الحلية“: ۴/۹۳\n(الصحيحة: ۸۱۵)","e":"سر میں جو اہمیت کان اور آنکھ کی ہے، دین میں وہی اہمیت سیدنا ابو بکر رضی اللہ عنہ اور سیدنا عمر رضی اللہ عنہ کو حاصل ہے۔ جس دین میں ابو بکر و عمر کی کوئی اہمیت نہ ہو، اس دین کی مثال بھی بہرے اور نابینا آدمی کی مثال ہے۔"}],[3275,"رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”حرا! تھم جا، نہیں ہے تجھ پر مگر نبی یا صدیق یا شہید۔“ یہ حدیث سیدنا سعید بن زید، سیدنا عثمان بن عفان، سیدنا انس بن مالک، سیدنا بریدہ بن حصیب اور سیدنا ابو ہریرہ رضی اللہ عنہم سے روایت کی گئی ہے۔","",{"t":"سیدنا عمر فاروق رضی اللہ عنہ کے فضائل و مناقب","k":"۱- أما حديث سعيد بن زيد: فأخرجه أبوداود: ۲/۲۶۴ ، والترمذي: ۴/۳۳۶ ، وابن ماجه: ۱/۶۱ ، وابن حبان: ۹/۶۹ - ۶۹۵۷ / الاحسان، والحاكم: ۳/۴۵۰ ، وأحمد: ۱/۱۸۷ و۱۸۸ و۱۸۹\n(الصحيحة: ۸۷۵)","e":"اس میں سیدنا ابو بکر صدیق رضی اللہ عنہ اور سیدنا عمر فاروق رضی اللہ عنہ کی عظمتوں کا بیان ہے، جنہیں بالترتیب صدیق اور شہید کے القاب سے نوازا گیا۔"}],[3276,"رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”قیامت کے روز ہر رشتہ (اور تعلق و قرابت) منقطع ہو جائے گا، سوائے میرے ازدواجی اور نسبی رشتے کے۔“ یہ حدیث سیدنا عبد اللہ بن عباس، سیدنا عمر بن خطاب، سیدنا مسور بن مخرمہ اور سیدنا عبد اللہ بن عمر رضی اللہ عنہم سے مروی ہے۔","",{"t":"سیدنا عمر رضی اللہ عنہ، سیدنا علی اور سیدہ فاطمہ رضی اللہ عنہا کے داماد","k":"(۱) - أما حديث ابن عباس فأخرجه المخلص في ”سبعة مجالس“: ۱/۵۱ ، والطبراني في ”المعجم الكبير“: ۳/۱۲۹ / ۱ ، والخطيب في ”التاريخ“: ۱۰/۲۷۱ ، والهروي في ”ذم الكلام“: ۲/۱۰۸ ، والضياء في ”المختارة“\n(الصحيحة: ۲۰۳۶)","e":"سیدنا عبد اللہ بن عمر رضی اللہ عنہ سے جو حدیث مروی ہے، اس کے الفاظ یہ ہیں: «كُلُّ نَسَبٍ وَ صِهْرٍ مُنْقَطِعٌ يَوْمَ الْقِيَامَةِ إِلَّا نَسَبِي وَ صِهْرِي -» (ابن عساكر: ۱۹/۶۰ / ۲ ، وهذا اسناد ضعيف جدا) ..... ”ہر نسبی اور ازدواجی رشتہ منقطع ہو جائے گا، سوائے میرے نسبی اور ازدواجی رشتے کے۔“ درج ذیل تفصیل سے اس حدیث کی مزید وضاحت ہو جاتی ہے: عقبہ بن عامر کہتے ہیں کہ سیدنا عمر رضی اللہ عنہ نے سیدنا علی رضی اللہ عنہ کی طرف ان کی بیٹی سے، جو سیدہ فاطمہ رضی اللہ عنہا کے بطن سے تھی، سے شادی کرنے کا بار بار پیغام بھیجا۔ ایک دن انھوں نے خود کہا: اے ابو الحسن! آپ کی طرف کثرت سے پیغام بھیجنے کی وجہ وہ حدیث ہے، جو میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنی، آپ صلی اللہ علیہ وسلم نے فرمایا: «كُلُّ سَبَبٍ وَ نَسَبٍ مُنْقَطِعٌ يَوْمَ الْقِيَامَةِ، الا سَبَبِي وَنَسَبِي -» ..... ”قیامت کے روز ہر رشتہ (اور تعلق و قرابت) منقطع ہو جائے گا، سوائے میرے ازدواجی اور نسبی رشتے کے۔“ میں چاہتا ہوں کہ آپ اہل بیت لوگوں کے ساتھ میری ازدواجی قرابت ہونی چاہیے۔ سیدنا علی رضی اللہ عنہ چلے گئے اور اپنی اس بیٹی کو میک اپ کرنے کا حکم دیا اور پھر اس کو امیر المومنین سیدنا عمر رضی اللہ عنہ کی طرف بھیج دیا۔ جب انھوں نے اس کو دیکھا تو اس کی طرف کھڑے ہوئے اور اس کی پنڈلی کو پکڑا اور کہا: اپنے باپ سے کہہ دینا کہ میں راضی ہوں، میں راضی ہوں، میں راضی ہوں۔ جب وہ بچی اپنے باپ سیدنا علی رضی اللہ عنہ کے پاس پہنچی تو انھوں نے پوچھا: امیر المومنین نے تجھے کیا کہا؟ اس نے کہا: انھوں نے مجھے بلایا اور قبول کیا، جب میں کھڑی ہوئی تو انھوں نے میری پنڈلی کو پکڑا اور کہا: اپنے ابو سے کہہ دینا کہ میں راضی ہوں۔ پھر انھوں نے ان سے اس کا نکاح کر دیا، اس کے بطن سے زید بن عمر پیدا ہوا، وہ نوجوانی تک زندہ رہے، پھر فوت ہو گئے۔ (اخرجه ابوبكر الشافعي في ”الفوائد“: ۷۳/۲۵۷ / ۱ ، وابن عدي: ۶/۲ ، والخطيب في ”التاريخ“: ۶/۱۸۲) سیدنا عمر رضی اللہ عنہ کے دل میں آل رسول کی یہ عزت تھی، آگے سے سیدنا علی رضی اللہ عنہ نے بھی ان کی تمنا پوری کرتے ہوئے ان کا احترام بجا لانے کی حد کر دی۔ اللہ تعالیٰ نے ان ہستیوں کے لیے ﴿رُحَمَاءُ بَيْنَهُمْ﴾ کے لقب کا کیا خوب انتخاب کیا۔"}],[3277,"ام المومنین سیدہ عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اپنی ران سے کپڑا ہٹا کر بیٹھے تھے، سیدنا ابو بکر رضی اللہ عنہ نے اندر آنے کی اجازت طلب کی، آپ نے اسی حالت میں اجازت دے دی، پھر سیدنا عمر رضی اللہ عنہ نے اجازت طلب کی، آپ نے اسی حالت میں اجازت دے دی۔ جب سیدنا عثمان رضی اللہ عنہ نے اجازت طلب کی تو آپ نے اپنا کپڑا نیچے لٹکا کر (ران کو ڈھانپ لیا)۔ جب یہ سارے لوگ چلے گئے تو میں نے پوچھا: اے اللہ کے رسول! ابو بکر نے آپ سے اجازت طلب کی، آپ اسی حالت پر تشریف فرما رہے ...... (لیکن جب عثمان نے اندر آنا چاہا تو اس طرح پردہ کر لیا)؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”عائشہ! کیا میں اس آدمی سے حیا نہ کروں کہ اللہ کی قسم! فرشتے بھی جس سے حیا کرتے ہیں۔“","",{"t":"سیدنا عثمان رضی اللہ عنہ کے فضائل و مناقب","k":"أخرجه ابن راهويه في ”مسنده“: ۱/۱۰۸ - ثم احال الالباني على الرقم: ۱۶۸۷ من صحيحته وفيه انه اخرج مسلم ايضا\n(الصحيحة: ۲۷۱۹)"}],[3278,"سعید بن عاص رضی اللہ عنہ کہتے ہیں کہ مجھے زوجہ رسول سیدہ عائشہ رضی اللہ عنہا اور سیدنا عثمان رضی اللہ عنہ (جیسا کہ صحیح مسلم وغیرہ کی روایت میں ہے) نے بیان کیا کہ سیدنا ابو بکر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم کے پاس آنے کی اجازت طلب کی، جبکہ آپ صلی اللہ علیہ وسلم سیدہ عائشہ رضی اللہ عنہا کی چادر اوڑھ کر اپنے بستر پر لیٹے ہوئے تھے، آپ صلی اللہ علیہ وسلم نے اسی حالت میں ابو بکر کو آنے کی اجازت دے دی، انھوں نے اپنا مدعا بیان کیا اور چلے گئے۔ پھر سیدنا عمر نے اجازت طلب کی، آپ صلی اللہ علیہ وسلم نے اسی حالت میں اجازت دے دی، انھوں نے اپنی ضرورت پوری کی اور چل دیے۔ سیدنا عثمان کہتے ہیں: ان کے بعد میں نے آپ صلی اللہ علیہ وسلم کے پاس آنے کی اجازت طلب کی، آپ صلی اللہ علیہ وسلم بیٹھ گئے اور عائشہ سے فرمایا: ”اچھی طرح کپڑے لپیٹ لو۔“ (پھر مجھے اجازت دی) میں نے اپنا کام پورا کیا اور چلا گیا۔ سیدہ عائشہ رضی اللہ عنہا نے پوچھا: اے اللہ کے رسول! کیا وجہ ہے کہ آپ نے ابو بکر اور عمر کے لیے وہ اہتمام نہیں کیا جو عثمان کے لیے کیا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”دراصل عثمان شرمیلا اور حیادار آدمی ہے، مجھے اندیشہ تھا کہ اگر اسی حالت میں اجازت دے دی تو وہ اپنی ضرورت کا اظہار نہیں کر سکے گا۔“","",{"t":"سیدنا عثمان رضی اللہ عنہ کے فضائل و مناقب","k":"أخرجه مسلم: ۷/۱۱۷ ، والبخاري في ”الأدب المفرد“: ۶۰۰ ، والطحاوي في ”شرح المعاني“ ۱/۲۷۴ و ”مشكل الآثار“: ۲/۲۹۰ - ۲۹۱ ، وأحمد: ۶/۱۵۵ و۱۶۷ ، وأبويعلى: ۳/۱۰۹۵\n(الصحيحة: ۱۶۸۷)","e":"اس میں سیدنا عثمان رضی اللہ عنہ کی فضیلت اور آپ صلی اللہ علیہ وسلم کے ہاں ان کی توقیر کا بیان ہے۔ چونکہ سیدنا عثمان رضی اللہ عنہ انتہائی حیادار تھے، ان کی طبیعت میں صفت حیا بدرجہ اتم پائی جاتی تھی، آپ صلی اللہ علیہ وسلم نے بھی ان کی اس طبیعت کا لحاظ رکھا اور مزید سنجیدگی اختیار کی۔ ان احادیث سے مطلق طور پر سیدنا عثمان کا صدیق و فاروق پر افضل ہونا لازم نہیں آتا، کیونکہ یہ ان کی جزوی فضیلت ہے، جس کی وجہ سے وہ دوسرے صحابہ سے ممتاز تھے۔"}],[3279,"سیدنا جابر بن عبد اللہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”عثمان جنت میں ہوں گے۔“","",{"t":"سیدنا عثمان رضی اللہ عنہ کے فضائل و مناقب","k":"رواه ابن عساكر: ۱۱/۱۰۱ / ۱\n(الصحيحة: ۱۴۳۵)"}],[3280,"رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس کا میں دوست ہوں، علی بھی اس کا دوست ہے۔ اے اللہ! تو علی کو دوست بنانے والے کا دوست بن جا اور اس سے دشمنی رکھنے والے کا دشمن بن جا۔“ یہ حدیث سیدنا زید بن ارقم، سیدنا سعد بن ابو وقاص، سیدنا بریدہ بن حصیب، سیدنا علی بن ابو طالب، سیدنا ابو ایوب انصاری، سیدنا براء بن عازب، سیدنا عبد اللہ بن عباس، سیدنا انس بن مالک، سیدنا ابو سعید خدری اور سیدنا ابو ہریرہ رضی اللہ عنہم سے مروی ہے۔","",{"t":"سیدنا علی رضی اللہ عنہ کے فضائل و مناقب","k":"(۱) - حديث زيد، وله عنه طرق خمس: الأولى: عن أبي الطفيل عنه: فأخرجه النسائي في ”خصائص علي“: ص۱۵ ، والحاكم: ۳/۱۰۹ ، وأحمد: ۱/۱۱۸ ، وابن أبي عاصم: ۱۳۶۵ ، والطبراني: ۴۹۶۹ - ۴۹۷۰ الثانية: عن ميمون أبي عبدالله به: فأخرجه أحمد: ۴/۳۷۲ ، والطبراني: ۵۰۹۲ الثالثة: عن أبي سليمان: فأخرجه أحمد: ۵/۳۷۰ ، وأبو القاسم هبة الله البغدادي في الثاني من ”الأمالي“: ق ۲/۲۰ الرابعة: عن يحيي بن جعدة عن زيد بن أرقم: فأخرجه الطبراني: ۴۹۸۶ الخامسة: عن عطية العوفي: فأخرجه أحمد: ۴/۳۶۸ ، والطبراني: ۵۰۶۸ - ۵۰۷۱ (۲) - حديث سعد بن أبي وقاص، وله عنه ثلاث طرق: الأولى: عن عبدالرحمن بن سابط عنه مرفوعا: فأخرجه ابن ماجه: ۱۲۱ الثانية: عن عبد الواحدي بن أيمن عن أبيه به: فأخرجه النسائي في ”الخصائص“: ۱۶ الثالثة: عن خيثمة بن عبد الرحمن عنه به وفيه الزيادة: فأخرجه الحاكم: ۳/۱۱۶ (۳) - حديث بريدة، وله عنه ثلاث طرق: الأولى: عن ابن عباس عنه: فأخرجه النسائي والحاكم: ۳/۱۱۰ ، وأحمد: ۵/۳۴۷ الثانية: عن ابن بريدة عن أبيه: فأخرجه النسائي وأحمد: ۵/۳۵۰ و۳۵۸ ، ۳۶۱ الثالثة: عن طاووس عن بريدة به: فأخرجه الطبراني في ”الصغير“: رقم - ۱۷۱ - الروض و ”الأوسط“ ۳۴۱ (۴) - حديث علي بن طالب، وله عنه تسع طرق: الأولى: عن عمرو بن سعيد أنه سمع علياً رضي الله عنه: فأخرجه النسائي - الثانية: عن زاذان بن عمر: فأخرجه أحمد: ۱/۸۴ ، وابن أبي عاصم: ۱۳۷۲ الثالثة و الرابعة: عن سعيد بن وهب و عن زيد بن يثيع: فأخرجه عبدالله بن أحمد في زوائد ”المسند“ ۱/۱۱۸ ، وعنه الضياء المقدسي في ”المختارة“: ۴۵۶ بتحقيقي الخامسة: عن شريك أيضا عن أبي أسحاق عن عمرو ذي مر بمثل حديث أبي أسحاق: فأخرجه عبدالله أيضا - السادسة: عن عبدالرحمن بن أبي ليلى: فأخرجه عبدالله بن أحمد: ۱/۱۱۹ السابعة و الثامنة: عن أبي مريم و رجل من جلساء علي عن علي: فأخرجه عبدالله: ۱/۱۵۲ التاسعة: عن طلحة بن مصرف: فأخرجه ابن أبي عاصم: ۱۳۷۳ (۵) - حديث أبي أيوب الأنصاري: فأخرجه أحمد: ۵/۴۱۹ ، والطبراني: ۴۰۵۲ و۴۰۵۳ (۶) - حديث البراء بن عازب: فأخرجه أحمد وابنه في زوائده: ۴/۲۸۱ ، وابن ماجه: ۱۱۶ (۷) - حديث ابن عباس: فأخرجه أحمد: ۱/۳۳۰ - ۳۳۱ ، وعنه الحاكم: ۳/۱۳۲ (۸ ، ۹ ، ۱۰) - حديث أنس بن مالك وأبي سعيد وأبي هريرة: فأخرجه الطبراني في ”الصغير“: ص۳۳ - هندية رقم ۱۱۶ - الروض، وفي ”الأوسط“: رقم ۲۴۴۲\n(الصحيحة: ۱۷۵۰)","e":"اس میں سیدنا علی رضی اللہ عنہ کی فضیلت اور ان کی آپ صلی اللہ علیہ وسلم سے مناسبت کا بیان ہے۔ ملا علی قاری نے کہا: اس کا معنی یہ ہے: میں جس سے دوستی کرتا ہوں، علی بھی اس سے دوستی رکھتا ہے جو مجھے دوست بنائے گا، علی اس کو دوست بنائے گا۔ لفظ ”مولیٰ“ کا اطلاق کئی معانی پر ہوتا ہے، جیسے رب، مالک، سیّد، منعم، جس پر انعام کیا جائے، آزاد کنندہ، آزاد شدہ، غلام، ناصر، محب، تابع، پڑوسی، چچا زاد، حلیف، عقد والا، وغیرہ۔ امام شافعی نے کہا: آپ صلی اللہ علیہ وسلم کی مراد اسلام کی دوستی ہے۔ کہا جاتا ہے کہ یہ حدیث بیان کرنے کا سبب یہ ہے کہ سیدنا اسامہ رضی اللہ عنہ نے سیدنا علی رضی اللہ عنہ سے کہا: تم میرے دوست نہیں ہو، میرے دوست تو رسول اللہ ہیں۔ لیکن آپ صلی اللہ علیہ وسلم نے اس کا ردّ کرتے ہوئے فرمایا: ”میں جس کا دوست ہوں، علی بھی اس کا دوست ہے۔“ شیعہ لوگوں کا خیال ہے کہ لفظ ”مولیٰ“ کے معانی متصرف کے ہیں، یعنی جن امور میں رسول اللہ صلی اللہ علیہ وسلم کو تصرف کرنے کا حق حاصل تھا، وہ سیدنا علی رضی اللہ عنہ کو بھی حاصل تھا، مومنوں کے معاملات بھی ایک چیز تھی، اس لیے سیدنا علی بھی امام ہوں گے۔ لیکن طیبی نے کہا: ولایت کو اس امامت پر محمول نہیں کیا جا سکتا، جس کا معنی مومنوں کے امور میں تصرف کرنا ہے، کیونکہ آپ صلی اللہ علیہ وسلم اپنی زندگی میں مستقل اور واحد متصرف تھے (اس وصف میں آپ صلی اللہ علیہ وسلم کے ساتھ کوئی دوسرا شریک نہ تھا)، اس لیے ولایت کو محبت اور اسلام دوستی پر محمول کرنا چاہیے۔ (ملخص از مرقاة المفاتيح: ۱۰/۴۷۳ ، ۴۷۴) امام البانی رحمہ اللہ کہتے ہیں: شیعہ لوگ سیدنا علی رضی اللہ عنہ کے بارے میں نبی کریم صلی اللہ علیہ وسلم کی یہ حدیث نقل کرتے ہیں: «إِنَّهُ خَلِيفَتِي مِنْ بَعْدِي -» ..... ”میرے بعد وہ خلیفہ ہوں گے۔“ لیکن یہ روایت کسی طرح بھی صحیح نہیں ہے، بلکہ یہ ان شیعوں کی باطل روایات میں سے ہے۔ تاریخی واقعہ بھی اس کی تکذیب پر دلالت کرتا ہے، کیونکہ اگر یہ حدیث آپ صلی اللہ علیہ وسلم کا قول ہوتی تو ایسے ہی واقع ہونا کہ سب سے پہلے سیدنا علی رضی اللہ عنہ خلیفہ بنتے اور سیدنا ابو بکر صدیق رضی اللہ عنہ خلیفہ نہ بنتے، کیونکہ آپ صلی اللہ علیہ وسلم کا فرمان وہی ہوتا ہے اور وہی میں جو بات جیسے بیان کی جاتی ہے، وہ اسی طرح واقع ہوتی ہے اور اللہ تعالیٰ اپنے وعدے کی مخالفت بھی نہیں کرتا۔ میں نے ضعیف (۲۹۳۲، ۲۹۳۳) میں اس قسم کی مرویات ذکر کر کے ان کا بطلان واضح کیا ہے۔ (صحیحہ: ۱۷۵۰)"}],[3281,"سیدنا ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ لوگوں نے سیدنا علی رضی اللہ عنہ کی شکایت کی، رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے، خطبہ دیا اور یہ بھی کہا: ”لوگو! علی کی شکایت مت لگایا کرو۔ اللہ کی قسم! وہ اللہ تعالیٰ کی ذات یا اللہ تعالیٰ کے راستے میں اس بات سے اعلیٰ ہے کہ اس کی شکایت کی جائے۔“","",{"t":"سیدنا علی رضی اللہ عنہ کے فضائل و مناقب","k":"أخرجه ابن اسحاق في ”السيرة“: ۴/۲۵۰ - هشام، ومن طريقه أحمد: ۳/۸۶\n(الصحيحة: ۲۴۷۹)","e":"اول تو کسی کو سیدنا علی رضی اللہ عنہ پر اعتراض نہیں ہونا چاہیے، اگر گر کوئی ہے تو وہ برداشت کرے، کیونکہ ان کی فضیلت و منقبت، مقام و مرتبہ اور شان و عظمت ان کے بشری تقاضوں پر غالب ہیں۔"}],[3282,"بلال بن یحییٰ کہتے ہیں: جب سیدنا عثمان رضی اللہ عنہ کو شہید کیا گیا تو سیدنا حذیفہ کو خواب آیا، انھیں کہا گیا: اے ابو عبد اللہ! عثمان کو تو شہید کر دیا گیا ہے اور لوگ اختلاف میں پڑ چکے ہیں، ایسے میں آپ کیا کہیں گے؟ انھوں نے کہا: مجھے سہارا دو۔ انھوں نے ان کو ایک آدمی کے سینے کا سہارا دیا۔ انھوں نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا: ”ابو الیقظان فطرت (اسلام) پر ہے اور اس کو مرنے تک یا انتہائی بوڑھا ہونے تک نہیں چھوڑے گا۔“","",{"t":"سیدنا علی رضی اللہ عنہ کے فضائل و مناقب","k":"أخرجه البزار في ”مسنده“: ۳/۲۵۲ / ۲۶۸۶ - الكشف، وأخرجه الطبراني في ”الاوسط“: ۱/۱۶۳ / ۳۰۴۳ مختصرا\n(الصحيحة: ۳۲۱۶)","e":"سیدنا عمار بن یاسر رضی اللہ عنہ کی کنیت ابو الیقظان تھی۔ وہ سیدنا عثمان رضی اللہ عنہ کی شہادت کے بعد سیدنا علی رضی اللہ عنہ کے ساتھ تھے اور ان ہی کے لشکر میں جنگ صفین میں شہید ہو گئے۔ اس سے معلوم ہوا کہ شہادت عثمان کے بعد سیدنا علی رضی اللہ عنہ حق پر تھے، اس موضوع پر ”اَلْفِتَنُ وَ أَشْرَاطُ السَّاعَةِ وَالْبَعْثُ“ میں ”سیدنا علی رضی اللہ عنہ حق پر تھے“ اور ”مشاجرات صحابہ کے بارے میں متاخرین کو کیا کہنا چاہیے؟“ کے عنوانوں میں تفصیلی بحث کی گئی ہے۔"}],[3283,"رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے علی کو تکلیف دی، اس نے مجھے تکلیف دی۔“ یہ حدیث سیدنا عمرو بن شاس، سیدنا سعد بن ابو وقاص اور سیدنا جابر بن عبد اللہ رضی اللہ عنہم سے مروی ہے۔","",{"t":"سیدنا علی رضی اللہ عنہ کے فضائل و مناقب","k":"(۱) أما حديث عمرو بن شاس؛ فرواه البخاري في ”التاريخ“: ۳/۲/۷۰۳ ، والفسوي في ”المعرفة“: ۱/۳۲۹ - ۳۳۰ ، وأحمد: ۳/۴۸۳ ، وابن حبان: ۲۲۰۲ ، و الحاكم: ۳/۱۲۲ ، وصححه، ووافقه الذهبي، وابن عساكر: ۱۲/۱۰۹ / ۱ (۲) وأما حديث سعد ابن أبي وقاص؛ فرواه الهيثم بن كليب في ”المسند“: ۲/۱۵ ، وأبو يعلى: ۷۷۰ ، والبزار: ۲۵۶۲ ، والقطيعي في زيادته على ”فضائل الصحابة“: ۱۰۷۸ (۳) - وأما حديث جابر بن عبد الله؛ فرواه ابن عساكر، وكذا السهمي في ”تاريخ جرجان“: ۳۲۵\n(الصحيحة: ۲۲۹۵)"}],[3284,"سیدہ ام سلمہ رضی اللہ عنہا کہتی ہیں: میں گواہی دیتی ہوں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا: ”جس نے علی سے محبت کی اس نے مجھ سے محبت کی اور جس نے مجھ سے محبت کی اس نے اللہ سے محبت کی۔ اور جس نے علی سے بغض رکھا، اس نے مجھ سے بغض رکھا اور جس نے مجھ سے بغض رکھا اس نے اللہ سے بغض رکھا۔“","",{"t":"سیدنا علی رضی اللہ عنہ کے فضائل و مناقب","k":"رواه المخلص في ”الفوائد المنتقاة“: ۱۰/۵ / ۱\n(الصحيحة: ۱۲۹۹)"}],[3285,"سیدنا عمران بن حصین رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدنا علی رضی اللہ عنہ کو امیر بنا کر ایک لشکر بھیجا، وہ اپنی جماعت کے ہمراہ چلے گئے، سیدنا علی رضی اللہ عنہ نے ایک لونڈی لے لی، دوسرے لوگوں نے اس چیز کو اچھا نہ سمجھا اور چار اصحاب رسول نے آپس میں معاہدہ کیا کہ اگر ہم رسول اللہ صلی اللہ علیہ وسلم کو ملے تو سیدنا علی رضی اللہ عنہ کے کے پر آپ کو آگاہ کریں گے۔ (اس وقت یہ معمول تھا کہ) مسلمان جب سفر سے واپس آتے تو سب سے پہلے رسول اللہ صلی اللہ علیہ وسلم کے پاس جاتے، آپ پر سلام کرتے، پھر اپنے گھروں کی طرف جاتے۔ جب یہ لشکر واپس آیا تو اس میں شریک افراد رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور نبی صلی اللہ علیہ وسلم کو سلام کیا۔ عہد و پیمان کے مطابق مذکورہ بالا چار افراد میں سے ایک کھڑا ہوا اور کہا: اے اللہ کے رسول! کیا آپ علی کو نہیں دیکھتے؟ انھوں نے ایسے ایسے کیا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے اس سے منہ پھیر لیا۔ پھر دوسرا کھڑا ہوا، اس نے بھی وہی بات کہی۔ آپ نے اس سے بھی اعراض کیا۔ پھر تیسرا کھڑا ہوا اور وہی بات کہی، رسول اللہ صلی اللہ علیہ وسلم نے اس سے بھی منہ پھیر لیا۔ پھر چوتھا کھڑا ہوا اور وہی بات کہی، آپ صلی اللہ علیہ وسلم اس کی طرف متوجہ ہوئے، آپ کے چہرے سے غیظ و غضب کا پتہ چل رہا تھا، اور فرمایا: ”تم علی کی شکایت کر کے کیا چاہتے ہو؟ بیشک علی مجھ سے ہے اور میں اس سے ہوں اور میرے بعد وہ ہر مومن کا دوست ہوگا۔“","",{"t":"سیدنا علی رضی اللہ عنہ کے فضائل و مناقب","k":"أخرجه الترمذي: ۳۷۱۳ ، والنسائي في ”الخصائص“: ۱۳ و۱۶ - ۱۷ ، وابن حبان: ۲۲۰۳ ، والحاكم: ۳/۱۱۰ ، والطيالسي في ”مسنده“: ۸۲۹ ، وأحمد: ۴/۴۳۷ - ۴۳۸ ، وابن عدي في ”الكامل“: ۲/۵۶۸ ، ۵۶۹\n(الصحيحة: ۲۲۲۳)","e":"اس قسم کی روایات اس حقیقت کا بین ثبوت ہیں کہ اگر صحابہ کرام میں کوئی قابل اعتراض چیز نظر آئے تو اسے نظر انداز کر دیا جائے اور ان کا یوں احترام کیا جائے کہ گویا وہ چیز ان سے سرزد نہیں ہوئی ہے۔ امام البانی رحمہ اللہ بیان کرتے ہیں: (خلاصہ:) محبت یا دوستی رکھنا، اس کا متضاد عداوت یا دشمنی رکھنا ہے، محبت اور دوستی ہر مسلمان کے لیے ثابت ہے، اور سیدنا علی رضی اللہ عنہ کبار مومنوں میں سے ہیں، وہ مومنوں کو دوست بنا لیں گے اور مومن ان کو۔ اس میں خارجیوں اور ناصبیوں پر ردّ کیا گیا ہے۔ لیکن اس حدیث کا یہ مطلب نہیں کہ مومنوں کے دوست صرف سیدنا علی رضی اللہ عنہ ہیں، اور کوئی نہیں ہے، غور کریں کہ سیدنا ابو ایوب انصاری رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «أَسْلَمُ وَغِفَارُ وَأَشْجَعُ، وَمُزَيْنَةُ وَجُهَيْنَةُ وَمَنْ كَانَ مِنْ بَنِي كَعْبٍ مَوَالِيَّ دُونَ النَّاسِ وَاللهُ وَرَسُولُهُ مَوْلَاهُمْ -» ..... ”اسلم، غفار، اشجع، مزینہ، جہینہ اور بنو کعب کے قبائل دوسرے لوگوں کی نسبت مخلص دوست ہیں اور ان کے دوست اللہ اور اس کا رسول ہیں۔“ (صحیحہ: ۱۴۵۵) اس لیے یہ حدیث قطعی طور پر اس امر پر دلالت نہیں کرتی کہ سیدنا علی رضی اللہ عنہ صدیق و فاروق کی نسبت خلافت کے زیادہ مستحق تھے، جیسا کہ شیعہ لوگوں کا خیال ہے، کیونکہ ”موالاة“ (یعنی دوستی و محبت) اور چیز ہے اور ”ولایت“ (یعنی امارت) اور چیز ہے۔ (صحیحہ: ۲۲۲۳)"}],[3286,"ابو عبد اللہ جدلی کہتے ہیں کہ مجھے سیدہ ام سلمہ رضی اللہ عنہا نے کہا: کیا رسول اللہ صلی اللہ علیہ وسلم کو تم لوگوں کی موجودگی میں منبروں پر برا بھلا کہا جا رہا ہے؟ میں نے کہا: سبحان اللہ! آپ کو کہاں برا بھلا کہا جا رہا ہے؟ انھوں نے کہا: کیا سیدنا علی بن ابو طالب رضی اللہ عنہ اور ان سے محبت کرنے والوں پر سب و شتم نہیں کیا جا رہا؟ اور میں گواہی دیتی ہوں کہ رسول اللہ صلی اللہ علیہ وسلم ان سے محبت کرتے تھے۔","",{"t":"سیدنا علی رضی اللہ عنہ کے فضائل و مناقب","k":"أخرجه الطبراني في ”المعجم الكبير“: ۲۳/۳۲۳ / ۷۳۸ ، و ”المعجم الأوسط“: ۶/۳۸۹ / ۵۸۲۸ ، و ”المعجم الصغير“: ۱۹۹ - هندية، وابو يعلى في ”مسنده“: ۱۲/۴۴۴\n(الصحيحة: ۳۳۳۲)","e":"سیدہ ام سلمہ رضی اللہ عنہا کا استدلال انتہائی قابل غور ہے۔ ہر صحابی کے بارے میں اسی قانون کو سامنے رکھنا چاہیے۔"}],[3287,"محمد بن اسامہ اپنے باپ سے روایت کرتے ہیں کہ سیدنا جعفر، سیدنا علی اور سیدنا زید بن حارثہ رضی اللہ عنہم جمع ہوئے، سیدنا جعفر نے کہا: میں رسول اللہ صلی اللہ علیہ وسلم کو تم سے زیادہ محبوب ہوں۔ سیدنا زید نے کہا: میں نبی کریم صلی اللہ علیہ وسلم کو تم دونوں سے بڑھ کر محبوب ہوں۔ انھوں نے کہا: چلو! رسول اللہ صلی اللہ علیہ وسلم کے پاس جا کر دریافت کرتے ہیں۔ سیدنا اسامہ بن زید رضی اللہ عنہ کہتے ہیں: وہ سب آئے، آپ صلی اللہ علیہ وسلم سے اجازت طلب کی۔ آپ نے مجھے فرمایا: جاؤ اور دیکھو، کون ہیں؟ میں نے کہا: جعفر، علی اور زید لوگ ہیں، میرے ابا جان! میں انھیں کیا کہوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”ان کو اندر آنے کی اجازت دے دو۔“ وہ سب اندر آ گئے اور کہا: آپ کو سب سے زیادہ محبوب کون ہے؟ آپ نے فرمایا: فاطمہ۔ انھوں نے کہا: ہم مردوں کے بارے میں سوال کر رہے ہیں۔ آپ نے فرمایا: ”جعفر! تمھارا اخلاق میرے اخلاق کے اور تمھاری جسمانی ساخت میری جسمانی ساخت کے مشابہ ہے اور تو مجھ سے اور میرے نسب میں سے ہے۔ علی! تم میرے داماد ہو، میرے بچوں (حسن و حسین) کے باپ ہو اور تم مجھ سے ہو اور میں تم سے ہوں اور زید! تم میرے دوست ہو، تم مجھ سے ہو، میں تمھارا ذمہ دار ہوں اور تم مجھے لوگوں میں محبوب ترین ہے۔“","",{"t":"سیدنا علی رضی اللہ عنہ کے فضائل و مناقب","k":"أخرجه أحمد: ۵/۲۰۴ ، والبخاري في ”التاريخ“: ۱/۱/۱۹ ، والحاكم: ۳/۲۱۷ ، والطبراني في ”المعجم الكبير“ رقم ۳۷۸ مختصرا\n(الصحيحة: ۱۵۵۰)","e":"آپ صلی اللہ علیہ وسلم نے ہر ایک کو اس کا مخصوص مقام عطا کر دیا، جس کی روشنی میں ہر کوئی دوسرے سے بالاتر نظر آ رہا ہے۔"}],[3288,"سیدنا علی رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”(اے علی!) تجھ سے محبت کرنے والا مومن اور تجھ سے بغض رکھنے والا منافق ہوگا۔“","",{"t":"سیدنا علی رضی اللہ عنہ کے فضائل و مناقب","k":"أخرجه مسلم: ۱/۶۱ ، والنسائي: ۲/۲۷۱ ، والترمذي: ۲/۳۰۱ ، وابن ماجه: ۱۱۴ ، وأحمد: ۱/۸۴ و۹۵ و۱۲۸ ، والخطيب في ”التاريخ“: ۱۴/۴۲۶\n(الصحيحة: ۱۷۲۰)","e":"سیدنا علی رضی اللہ عنہ کی ذات کو ایمان اور نفاق کا معیار قرار دیا گیا ہے۔ آپ کا محب مومن ہے اور بغض رکھنے والا کافر۔"}],[3289,"نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”علی میرا قرضہ ادا کرے گا۔“ یہ حدیث سیدنا انس بن مالک، سیدنا حبشی بن جنادہ اور سیدنا سعد بن ابو وقاص رضی اللہ عنہم سے مروی ہے۔","",{"t":"سیدنا علی رضی اللہ عنہ کے فضائل و مناقب","k":"(۱) - أما حديث أنس: فأخرجه البزار: ص۲۶۸ ، والديلمي في ”مسند الفردوس“: ۲/۲۹۷ (۲) - وأما حديث حبشي: فأخرجه أحمد: ۴/۱۶۴ ، وابن عساكر في ”تاريخ دمشق“: ۱۲/۱۵۰ / ۱ ، والترمذي: ۲/۲۹۹ ، وابن ماجه: ۱۱۹ (۳) - وأما حديث سعد: فأخرجه النسائي في ”خصائص علي“: ص۳ ، والبزار في ”مسنده“: ص۲۶۶\n(الصحيحة: ۱۹۸۰)","e":"جامع ترمذی اور ابن ماجہ کی روایت کے الفاظ یہ ہیں: «عَلِيٌّ مِنِّي وَأَنَا مِنْ عَلِيٍّ، وَلَا يُؤَدِّي عَنِّي إِلَّا أَنَا أَوْ عَلِيٌّ» ..... ”علی مجھ سے ہے اور میں علی سے ہوں اور میری طرف سے ادائیگی کرنے والا میں خود ہوں گا یا علی ہوگا۔“ دراصل عربوں کے ہاں یہ رواج تھا کہ مختلف قبائل یا شخصیات کے مابین معاہدہ کرنے یا عہد توڑنے یا اس کو مضبوط و مستحکم کرنے کی بات چلتی تو یہ ذمہ داری قوم کا سردار خود ادا کرتا تھا یا اس کا کوئی قریبی بیٹا۔ جیسے وہ سیدنا ابو بکر رضی اللہ عنہ کے حج کے لیے روانہ ہو جانے کے بعد آپ صلی اللہ علیہ وسلم نے یہ فیصلہ کیا کہ اعلان براءت کے لیے سیدنا علی رضی اللہ عنہ کو بھیجا جانا چاہیے، پھر عملی طور پر ایسے ہی کیا گیا۔"}],[3290,"سیدنا ابو سعید خدری رضی اللہ عنہ کہتے ہیں: ہم بیٹھے رسول اللہ صلی اللہ علیہ وسلم کا انتظار کر رہے تھے، آپ اپنی ایک بیوی کے گھر سے نکلے اور ہمارے پاس تشریف لائے۔ ہم کھڑے ہوئے (اور) آپ کے ساتھ چل دیے، آپ کا جوتا ٹوٹ گیا، سیدنا علی رضی اللہ عنہ اس کو سلائی کرنے کی خاطر پیچھے رہ گئے۔ رسول اللہ صلی اللہ علیہ وسلم چلتے رہے اور ہم بھی آپ کے ساتھ چلتے رہے۔ ایک مقام پر سیدنا علی کے انتظار میں ٹھہر گئے، ہم بھی آپ کے ساتھ رک گئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”تم میں سے بعض لوگ میری طرح اس قرآن کی تفسیر کے مطابق جہاد کرتے ہیں۔“ ہم جھانکنے لگ گئے اور ہم میں ابو بکر اور عمر بھی تھے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”نہیں، میری مراد جوتے کی سلائی کرنے والا (علی) ہے۔“ ہم سیدنا علی رضی اللہ عنہ کو خوشخبری دینے کے لیے آئے، لیکن ایسے لگ رہا تھا کہ انھوں نے یہ بشارت خود سن لی تھی۔","",{"t":"سیدنا علی رضی اللہ عنہ کے فضائل و مناقب","k":"أخرجه النسائي في ”خصائص علي“: ص۲۹ ، وابن حبان: ۲۲۰۷ ، والحاكم: ۳/۱۲۲ ، وأحمد: ۳/۳۳ و۸۲ ، وابو يعلى: ۱/۳۰۳ - ۳۰۴ ، وابو نعيم في ”الحلية“: ۱/۶۷ ، وابن عساكر: ۱۲/۱۷۹ - ۲/۱۸۰\n(الصحيحة: ۲۴۸۷)"}],[3291,"مسور کہتے ہیں کہ حسن بن حسن نے میری بیٹی سے شادی کرنے کے لیے مجھے پیغام بھیجا، میں نے قاصد کو کہا: اسے کہنا کہ وہ مجھے شام کو ملے۔ اس نے مسور سے (وقت کے مطابق) ملاقات کی۔ مسور نے اللہ تعالی کی حمد و ثنا بیان کی اور کہا: اللہ کی قسم! مجھے کوئی نسبی اور ازدواجی رشتہ و قرابت تمھارے نسب و حسب اور نسبی و ازدواجی تعلق و قرابت سے بڑھ کر محبوب نہیں ہے۔ دراصل بات یہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”فاطمہ میرے (بدن کا) ٹکڑا ہے، جو چیز اسے پریشان کرتی ہے وہ مجھے بھی پریشان کرتی ہے، جو چیز اسے خوش کرتی ہے وہ مجھے بھی خوش کرتی ہے اور قیامت والے دن سب احباب و انساب منقطع ہو جائیں گے، ماسوائے میرے نسب، رشتہ قرابت اور دامادی کے۔“ (اس حدیث کے بعد غور کر کے) تیرے گھر سیدہ فاطمہ رضی اللہ عنہا کی بیٹی ہے، اگر میں نے اپنی بیٹی سے بھی تیری شادی کر دی تو وہ پریشان ہوگی (ایسی صورت میں میرا اور میری بیٹی کا کیا بنے گا؟) حسن بن حسن نے اسے معذور سمجھا اور چلا دیے۔","",{"t":"سیدہ فاطمہ رضی اللہ عنہا کی فضیلت","k":"أخرجه أحمد: ۴/۳۲۳ ، ومن طريقه الحاكم: ۳/۱۵۸ ، وعبد الله بن أحمد: ۴/۳۳۲ ، والحديث أخرجه البخاري: ۱۱/۸۴ والنسائي في ”الخصائص“: ص۲۵ بلفظ: ((فاطمة بضعة مني فمن اغضبها اغضبني))\n(الصحيحة: ۱۹۹۵)"}],[3292,"سیدنا عبد اللہ بن عباس رضی اللہ عنہما بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”حضرت مریم بنت عمران کے بعد جنتی عورتوں کی سردار یہ (تین عورتیں ہیں): فاطمہ، خدیجہ اور فرعون کی بیوی آسیہ ہیں۔“","",{"t":"سیدہ فاطمہ رضی اللہ عنہا کی فضیلت","k":"رواه الطبراني: ۳/۱۵۰ / ۲\n(الصحيحة: ۱۴۲۴)"}],[3293,"ام المومنین سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ ہم نبی کریم صلی اللہ علیہ وسلم کی بیویاں آپ کے پاس جمع تھیں، کوئی ایک بھی غیر حاضر نہیں تھی، سیدہ فاطمہ رضی اللہ عنہا آپ کے پاس چل کر آ رہی تھیں، ان کے چلنے کا انداز بالکل رسول اللہ صلی اللہ علیہ وسلم والا تھا۔ جب آپ نے ان کو دیکھا تو یوں خوش آمدید کہا: ”میری بیٹی! مرحبا۔“ پھر ان کو اپنی دائیں یا بائیں جانب بٹھا لیا، آپ نے ان سے کوئی سرگوشی کی، وہ شد و مد سے رونے لگ گئیں۔ جب آپ نے ان کے غم و الم کو دیکھا تو دوسری دفعہ سرگوشی کی، اب کی بار انھوں نے ہنسنا شروع کر دیا۔ آپ صلی اللہ علیہ وسلم کی بیویوں میں سے میں نے اس سے کہا: رسول اللہ صلی اللہ علیہ وسلم نے تم سے کوئی راز دارانہ بات کی، لیکن تو نے رونا شروع کر دیا۔ جب رسول اللہ صلی اللہ علیہ وسلم اٹھ کر چلے گئے تو میں نے ان سے پوچھا: آپ نے تم سے کیا سرگوشی کی ہے؟ انھوں نے کہا: میں رسول اللہ صلی اللہ علیہ وسلم کا راز فاش نہیں کر سکتی۔ جب آپ فوت ہو گئے تو میں نے سیدہ فاطمہ سے کہا: میں تجھے پر اپنے حق کا واسطہ دے کر پوچھتی ہوں کہ اب تم مجھے ضرور بتاؤ گی۔ انھوں نے کہا: ٹھیک ہے اب، بتا دیتی ہوں۔ انھوں نے مجھے بتلایا کہ آپ نے پہلی دفعہ والی سرگوشی میں مجھے فرمایا: ”جبرئیل مجھ سے ہر سال ایک دفعہ قرآن مجید کا دور کیا کرتے تھے اور اس سال دو دفعہ کیا، ایسے معلوم ہوتا ہے کہ میری موت کا وقت قریب آ چکا ہے، لہذا اللہ سے ڈرنا اور صبر کرنا، میں تیرے لیے بہترین پیش رو ہوں گا۔“ یہ بات سن کر مجھے رونا آ گیا، آپ دیکھ ہی رہی تھیں۔ جب آپ صلی اللہ علیہ وسلم نے میری بے چینی اور گھبراہٹ کو دیکھا تو فرمایا: ”فاطمہ! اگر تمھیں (جنت میں) مومنوں کی عورتوں یا اس امت کی عورتوں کی سرداری دی جائے تو راضی ہو جاؤ گی؟“ یہ سن کر میں ہنس پڑی، آپ دیکھ ہی رہی تھیں۔","",{"t":"سیدہ فاطمہ رضی اللہ عنہا کی فضیلت","k":"أخرجه البخاري: ۶۲۸۶ ، ومسلم: ۷/۱۴۲ - ۱۴۴ ، والنسائي في ”الكبرى“: ۵/۹۶ ، وابن ماجه: ۱۶۲۱ ، والطحاوي في ”مشكل الآثار“: ۴۸ - ۴۹ ، وابن سعد: ۸/۲۶ - ۲۷ ، وأحمد: ۶/۲۸۲\n(الصحيحة: ۲۹۴۸)"}],[3294,"عروہ، سیدہ عائشہ رضی اللہ عنہا سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”زینب میری افضل بیٹی ہے، اسے میری وجہ سے تکلیف پہنچی۔“ جب یہ حدیث علی بن حسین (بن فاطمہ) کو پہنچی تو وہ عروہ کے پاس آئے اور کہا: مجھے ایک حدیث موصول ہوئی ہے اس میں (میری دادی) سیدہ فاطمہ رضی اللہ عنہا کی تنقیص کی گئی ہے، اس کی کیا حقیقت ہے؟ عروہ نے کہا: میں نہیں چاہتا کہ مجھے اتنا کچھ (مال و دولت) مل جائے اور میں سیدہ فاطمہ کے حق میں تنقیص کروں۔ آج کے بعد میرا تجھ سے معاہدہ ہے کہ میں یہ حدیث بیان نہیں کروں گا۔","",{"t":"سیدہ زینب رضی اللہ عنہا کی فضیلت","k":"أخرجه الطبراني في ”المعجم الأوسط“: ۱/۲۹۰ / ۴۸۶۳ ، والبزار: ۳/۲۴۲ ، والطبراني ايضا في ”المعجم الكبير“: ۲۲/۴۳۱ / ۱۰۵۱ أتم منه\n(الصحيحة: ۳۰۷۱)","e":"اس حدیث سے سیدہ زینت کی افضلیت ثابت ہوتی ہے، (نَعُوْذُ بِاللہِ) اس سے آپ صلی اللہ علیہ وسلم کی کسی بیٹی کی تنقیص لازم نہیں آتی، جیسا کہ علی بن حسین کو وہم ہوا ہے۔"}],[3295,"سیدنا ابو ہریرہ رضی اللہ عنہ کہتے ہیں: جب میں سیدنا حسن رضی اللہ عنہ کو دیکھتا ہوں تو میری آنکھوں سے آنسو بہہ پڑتے ہیں، وجہ یہ ہے کہ ایک دن نبی کریم صلی اللہ علیہ وسلم باہر تشریف لائے، میں مسجد میں تھا، آپ نے میرا ہاتھ پکڑا، میں آپ کے ساتھ چل دیا، آپ نے مجھ سے کوئی بات نہیں کی، حتی کہ ہم بنو قینقاع کے بازار پہنچ گئے، آپ نے وہاں چکر لگایا اور ادھر ادھر دیکھا، پھر واپس پلٹ آئے اور میں بھی آپ کے ساتھ تھا، یہاں تک کہ ہم مسجد میں پہنچ گئے۔ آپ وہاں حبوہ باندھ کر بیٹھ گئے اور فرمایا: ”چھوٹا بچہ کدھر ہے؟ چھوٹے کو ذرا بلا کر لاؤ۔“ سو سیدنا حسن رضی اللہ عنہ دوڑتا ہوا آیا، آپ کی گود میں گر پڑا اور اپنا ہاتھ آپ کی ڈاڑھی میں داخل کرنے لگا۔ آپ صلی اللہ علیہ وسلم نے اپنا منہ کھول کر اس کے منہ کو اپنے منہ میں داخل کیا، پھر فرمایا: ”اے اللہ! میں اسے محبت کرتا ہوں، تو اس سے بھی اور اس سے محبت کرنے والے سے بھی محبت کر۔“","",{"t":"سیدنا حسن و حسین رضی اللہ عنہما کی فضیلت","k":"أخرجه البخاري في ”الأدب المفرد“: ۱۱۸۳ ، وأحمد: ۱/۵۳۲ ، وابنه عبدالله في ”فضائل الصحابة“: ۲/۷۸۸ / ۱۴۰۷ ، والحاكم: ۳/۱۷۸ ، والحديث أخرجه البخاري: ۵۸۸۴ مختصرا وكذا مسلم: ۷/۱۳۰\n(الصحيحة: ۲۸۰۷)","e":"اس میں سیدنا حسن رضی اللہ عنہ کی شان و عظمت اور سیدنا ابو ہریرہ رضی اللہ عنہ کی رسول اللہ صلی اللہ علیہ وسلم سے والہانہ محبت کا بیان ہے۔"}],[3296,"سیدنا برا رضی اللہ عنہ کہتے ہیں کہ میں نے نبی کریم صلی اللہ علیہ وسلم کو دیکھا، سیدنا حسن بن علی رضی اللہ عنہ ان کے کندھے پر بیٹھے تھے، آپ صلی اللہ علیہ وسلم فرما رہے تھے: ”اے اللہ! میں اس سے محبت کرتا ہوں، تو بھی اس سے محبت فرما۔“","",{"t":"سیدنا حسن و حسین رضی اللہ عنہما کی فضیلت","k":"أخرجه البخاري: ۳۷۴۹ ، ومسلم: ۷/۱۳۰ ، وأحمد: ۴/۲۸۳ - ۲۸۴ ، وكذا الطيالسي: ۷۳۲ ، والطبراني في ”المعجم الكبير“: ۲۵۸۲\n(الصحيحة: ۲۷۸۹)"}],[3297,"سیدنا اسامہ بن زید رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مجھے اور سیدنا حسن رضی اللہ عنہ کو پکڑ کر کہتے: ”اے اللہ! میں ان دونوں سے محبت کرتا ہوں، تو بھی ان سے محبت کر۔“","",{"t":"سیدنا حسن و حسین رضی اللہ عنہما کی فضیلت","k":"أخرجه البخاري: ۳۷۳۵ ، ۳۷۴۷ ، وأحمد: ۵/۲۱۰ ، وكذا ابن أبي شيبة في ”المصنف“: ۱۲/۹۸ / ۱۲۲۳۲ ، وابن سعد في ”الطبقات“: ۴/۶۲ ، والطبراني في ”المعجم الكبير“: ۳/۳۹ / ۲۶۴۲\n(الصحيحة: ۳۳۵۴)"}],[3298,"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو کسی جنتی آدمی کو دیکھ کر خوش ہونا چاہتا ہے، وہ حسین بن علی کو دیکھ لے۔“","",{"t":"سیدنا حسن و حسین رضی اللہ عنہما کی فضیلت","k":"أخرجه ابو يعلى في ”مسنده“: ۳/۱۸۷۴ ، وعنه ابن حبان: ۲۲۳۷\n(الصحيحة: ۴۰۰۳)"}],[3299,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے، اس حال میں کہ آپ کے ساتھ حسن و حسین بھی تھے، ایک ایک کندھے پر تھا اور دوسرا دوسرے پر۔ آپ کبھی ایک کو بوسہ لیتے اور کبھی دوسرے کو چومتے، حتی کہ ہمارے پاس پہنچ گئے۔ ایک آدمی نے آپ صلی اللہ علیہ وسلم سے کہا: آپ ان سے محبت کرتے ہیں۔ آپ نے فرمایا: ”جس نے ان سے محبت کی، اس نے مجھ سے محبت کی اور جس نے ان سے بغض رکھا اس نے مجھ سے بغض رکھا۔“","",{"t":"سیدنا حسن و حسین رضی اللہ عنہما کی فضیلت","k":"أخرجه أحمد في ”المسند“: ۲/۴۴۰ ، وفي ”الفضائل“: ۲/۷۷۷ / ۱۳۶۷ ، ومن طريقه الحاكم: ۳/۱۶۶ ، والبزار: ۳/۲۲۷ / ۲۲۶۷\n(الصحيحة: ۲۸۹۵)"}],[3300,"عبد الرحمن بن ابو نعم کہتے ہیں کہ ایک آدمی نے سیدنا عبد اللہ بن عمر رضی اللہ عنہ سے اس کپڑے کے بارے میں دریافت کیا جس کو مچھر کا خون لگ جاتا ہے، میں بھی وہاں بیٹھا تھا۔ انھوں نے کہا: تو کہاں سے ہے؟ اس نے کہا: عراق سے۔ سیدنا عبد اللہ بن عمر نے کہا: دیکھو اس آدمی کو، یہ مچھر کے خون کے بارے میں سوال کرتا ہے؟ (یہ ایسے ظالم ہیں کہ) انھوں نے رسول اللہ صلی اللہ علیہ وسلم کے نواسے کو شہید کر دیا اور میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا تھا: ”بیشک حسن اور حسین میری دنیا کے خوشبودار پودے ہیں۔“","",{"t":"سیدنا حسن و حسین رضی اللہ عنہما کی فضیلت","k":"أخرجه البخاري: ۷/۷۹ ، ۱۰/۳۵۰ - فتح، والترمذي: ۴/۳۶۹ - ۳۷۰ ، وأحمد: ۲/۹۲ ، ۱۱۴\n(الصحيحة: ۵۶۴)"}],[3301,"خالد بن معدان کہتے ہیں کہ سیدنا مقدام بن معدی کرب اور سیدنا عمرو بن اسود رضی اللہ عنہما سیدنا معاویہ رضی اللہ عنہ کے پاس گئے، سیدنا معاویہ نے سیدنا مقدام سے کہا: کیا تم جانتے ہو کہ سیدنا حسن بن علی رضی اللہ عنہ فوت ہو گئے ہیں؟ انھوں نے ”إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ“ کہا۔ سیدنا معاویہ نے ان سے پوچھا: کیا تم اس خبر کو آزمائش سمجھتے ہو؟ انھوں نے کہا: میں اس واقعہ کو ابتلا و آزمائش کیوں نہ سمجھوں، حالانکہ رسول اللہ صلی اللہ علیہ وسلم نے سیدنا حسن کو اپنی گود میں بٹھایا اور فرمایا: ”حسن مجھ سے ہے اور حسین، علی سے ہے۔“","",{"t":"سیدنا حسن و حسین رضی اللہ عنہما کی فضیلت","k":"أخرجه أبوداود: ۲/۱۸۲ ، وأحمد: ۴/۱۳۲ ، والطبراني في ”الكبير“: ۳/۳۴ ، وابن عساكر: ۴/۲۵۸ / ۱\n(الصحيحة: ۸۱۱)"}],[3302,"نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”حسن اور حسین جنتی نوجوانوں کے سردار ہوں گے۔“ یہ حدیث سیدنا ابو سعید خدری، سیدنا حذیفہ بن یمان، سیدنا علی بن ابو طالب، سیدنا عمر بن خطاب، سیدنا عبد اللہ بن مسعود، سیدنا عبد اللہ بن عمر، سیدنا برا بن عازب، سیدنا ابو ہریرہ، سیدنا جابر بن عبد اللہ اور سیدنا قرہ بن ایاس رضی اللہ عنہم سے روایت کی گئی ہے۔","",{"t":"سیدنا حسن و حسین رضی اللہ عنہما کی فضیلت","k":"۱- أما حديث أبي سعيد: فأخرجه الترمذي: ۴/۳۳۹ ، والحاكم: ۳/۱۶۶ ، والطبراني: ۱/۱۲۳ / ۱ ، وأبو نعيم في ”الحلية“: ۳/۶۲ ، ۶۴ ، ۸۰ ، ۸۲ ، وابن عساكر: ۱۸/۴۷ / ۱ ۲- وأما حديث حذيفة: فأخرجه الترمذي: ۲/۳۰۷ ، وابن حبان: ۲۲۲۹ ، وأحمد: ۳۹۱ ، والطبراني: ۱/۱۲۳ / ۱ ، والخطيب: ۶/۳۷۲ ، وابن عساكر في ”تاريخ دمشق“: ۴/۲۵۵ / ۲ ۳- وأما حديث علي: فأخرجه أبو نعيم: ۴/۱۴۰ ، والخطيب: ۱۲/۴ ، والطبراني: ۱/۱۲۲ / ۲ ، وابن عساكر: ۴/۲۵۶ / ۱ ، والخطيب: ۱/۱۴۰ ، وعنه ابن عساكر: ۴/۲۵۶ / ۱ ، وابن أبي شيبة: ۱۲/۱۲۲۲۸ ، والبزار: ۳/۲۳۴ ۴- وأما حديث عمر بن الخطاب: فأخرجه الطبراني: ۱/۱۲۲ / ۲ ، وأبو نعيم: ۴/۱۳۹ ۵- وأما حديث ابن مسعود: فأخرجه الحاكم: ۳/۱۶۷ ، وأبو نعيم: ۵/۵۸ ۶- وأما حديث عبدالله ابن عمر: فأخرجه الحاكم: ۳/۱۶۷ ، وابن عساكر: ۴/۲۵۶ / ۱ ۷- وأما حديث البراء؛ فقال الهيثمي: ۹/۱۸۴ ”وراه الطبراني واسناده حسن“ ۸- وأما حديث أبي هريرة؛ فأخرجه الطبراني: ۱/۱۲۳ / ۱ ۹- وأما حديث جابر؛ فأخرجه البزار: ۳/۲۳۰ / ۲۶۳۶ ، والطبراني، وابن عساكر: ۴/۲۵۶ / ۱\n(الصحيحة: ۷۹۶)","e":"”حسن و حسین جنتی نوجوانوں کے سردار ہوں گے“ اس منقبت کے مختلف معانی بیان کیے گئے ہیں: (۱) جو لوگ نوجوانی میں اللہ کے راستے میں فوت ہو کر جنت میں داخل ہوں گے، حسن و حسین ان سب سے افضل ہوں گے۔ (۲) آپ صلی اللہ علیہ وسلم نے جس وقت یہ حدیث ارشاد فرمائی تھی، اس زمانے کے جنتی نوجوانوں کے یہ سردار ہوں گے۔ (۳) جو لوگ جوانی میں فوت ہوں گے ان کے سردار سیدنا حسن اور سیدنا حسین رضی اللہ عنہما ہوں گے۔ آخری معنی حدیث مبارکہ کے عام الفاظ سے زیادہ مناسبت رکھتا ہے۔"}],[3303,"سیدنا یعلی بن مرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”حسین مجھ سے ہے اور میں حسین سے ہوں، اللہ تعالی اس سے محبت کرے جو حسین سے محبت کرتا ہے، حسین امتوں میں سے ایک امت ہے۔“","",{"t":"سیدنا حسن و حسین رضی اللہ عنہما کی فضیلت","k":"أخرجه البخاري في \"التاريخ\" ۴/۲/۴۱۵ ، والترمذي: ۳۷۷۷ ، وابن ماجه: ۱۴۴ ، وابن حبان: ۲۲۴۰ ، والحاكم: ۳/۱۷۷ ، وأحمد: ۴/۱۷۲\n(الصحيحة: ۱۲۲۷)","e":"یعنی خیر و بھلائی میں ایک امت کی مانند ہیں اور یہ بھی ممکن ہے کہ آپ صلی اللہ علیہ وسلم کی مراد یہ ہو کہ اللہ تعالی ان کی اولاد میں برکت ڈالے گا اور وہ ایک بڑی امت ہو جائے گی اور ایسے ہی ہوا، ہزار ہا صحیح النسب سادات موجود ہیں، جن کا سلسلہ نسب حسن یا حسین سے ملتا ہے۔"}],[3304,"ابو فاختہ بیان کرتے ہیں کہ سیدنا علی رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے اور ہمارے ہاں ہی رات گزاری، حسن و حسین سو رہے تھے۔ (رات کو) حسن نے پانی مانگا۔ رسول اللہ صلی اللہ علیہ وسلم ہمارے مشکیزے کی طرف گئے، پیالے میں پانی نکالا، پھر اسے پلانے کے لیے لے آئے، (اب حسن کی بجائے وہ پیالہ) حسین نے پینے کے لیے پکڑنا چاہا، لیکن آپ نے اسے نہ پینے دیا، پھر حسن سے ابتدا کی۔ سیدہ فاطمہ رضی اللہ عنہا نے کہا: اے اللہ کے رسول! ایسے لگتا ہے کہ آپ کو حسن زیادہ محبوب ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”یہ بات نہیں ہے، (دراصل) حسن نے پانی پہلے مانگا تھا (اس لیے پہلے پینے کا حق بھی اسی کا ہے)۔“ پھر فرمایا: ”میں، تو، یہ دونوں اور یہ سونے والے (علی رضی اللہ عنہ) روزِ قیامت ایک مقام میں ہوں گے۔“ ان دونوں سے مراد سیدہ فاطمہ کے بیٹے حسن اور حسین ہیں۔","",{"t":"سیدنا حسن و حسین اور ان کے والدین کی عظمت","k":"أخرجه الطيالسي في \"مسنده\": ۲۶/۱۹۰ ، والطبراني في \"المعجم الكبير\": ۳/۳۱/۲۶۲۲ ، والبزار في \"مسنده\": ۳/۲۲۳/۲۶۱۶ ، وأخرج أحمد: ۱/۱۰۱ نحوه\n(الصحيحة: ۳۳۱۹)"}],[3305,"سیدہ ام الفضل بنت حارث رضی اللہ عنہا سے روایت ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں اور کہا: اے اللہ کے رسول! میں نے رات کو قبیح خواب دیکھا۔ آپ صلی اللہ علیہ وسلم نے پوچھا: ”وہ کیا ہے؟“ اس نے کہا: وہ بہت سخت ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”آخر وہ ہے کیا؟“ اس نے کہا: مجھے ایسے لگا کہ آپ کے جسم کا ایک ٹکڑا کاٹ کر میری گود میں پھینکا گیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”تو نے تو عمدہ خواب دیکھا ہے، (اس کی تعبیر یہ ہے کہ) ان شاء اللہ میری بیٹی فاطمہ کا بچہ پیدا ہو گا جو تیری گود میں ہو گا۔“ واقعی سیدہ فاطمہ رضی اللہ عنہا کا بچہ حسین پیدا ہوا جو میری گود میں تھا، جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا۔ ایک دن میں رسول اللہ صلی اللہ علیہ وسلم کے پاس گئی اور حسین کو آپ کی گود میں رکھ دیا۔ جب آپ صلی اللہ علیہ وسلم کی طرف متوجہ ہوئی تو آپ کی آنکھوں سے آنسو بہہ رہے تھے۔ میں نے کہا: اے اللہ کے نبی! میرے ماں باپ آپ پر قربان ہوں، آپ کو کیا ہو گیا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جبریل علیہ السلام میرے پاس آئے اور مجھے بتلایا کہ میری امت میرے اس بیٹے کو قتل کر دے گی۔“ میں نے کہا: یہ بیٹا (حسین)؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”ہاں، وہ میرے پاس اس علاقے کی سرخ مٹی بھی لائے۔“","",{"t":"سیدنا حسین رضی اللہ عنہ کے مقتل کی حیثیت","k":"أخرجه الحاكم: ۳/۱۷۶-۱۷۷ ، وعنه البيهقي في \"الدلائل\": ۶/۴۶۹\n(الصحيحة: ۸۲۱)","i":"§سیدنا حسین رضی اللہ عنہ کی شہادت کی پیشین گوئی"}],[3306,"سیدہ عائشہ و سیدہ ام سلمہ رضی اللہ عنہما بیان کرتی ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے ان میں سے کسی ایک کو فرمایا: ”آج گھر میں میرے پاس ایسا فرشتہ آیا، جو پہلے کبھی نہیں آیا تھا، اس نے مجھے کہا: آپ کا یہ حسین بیٹا قتل ہو جائے گا، اگر آپ چاہتے ہیں تو میں اس کے مقتل (جائے قتل) کی مٹی آپ کو دکھا دیتا ہوں۔“ پھر اس نے سرخ مٹی نکال (کر مجھے دکھائی)۔","",{"t":"سیدنا حسین رضی اللہ عنہ کی شہادت کی پیشین گوئی","k":"أخرجه الحاكم: ۳/۱۷۶-۱۷۷ ، وعنه البيهقي في \"الدلائل\": ۶/۴۶۹\n(الصحيحة: ۸۲۲)"}],[3307,"عبداللہ بن نجی اپنے باپ سے روایت کرتے ہیں کہ وہ طہارت والے پانی کا برتن اٹھا کر سیدنا علی رضی اللہ عنہ کے ساتھ چل رہے تھے، جب وہ صفین کی طرف جاتے ہوئے نینوی مقام تک پہنچے، تو سیدنا علی نے آواز دی: ابو عبداللہ! ٹھہر جاؤ، دریائے فرات کے کنارے ٹھہر جاؤ۔ میں نے کہا: ادھر کیا ہے؟ انھوں نے کہا: میں ایک دن نبی کریم صلی اللہ علیہ وسلم کے پاس گیا، اس حال میں کہ آپ کی آنکھیں اشک بار تھیں۔ میں نے کہا: اے اللہ کے نبی! کسی نے آپ کو غصہ دلایا ہے؟ آپ کی آنکھیں کیوں آنسو بہا رہی ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”آپ کی آمد سے قبل جبریل امین میرے پاس سے اٹھ کر گئے ہیں، انھوں نے مجھے خبر دی ہے کہ حسین کو دریائے فرات کے کنارے قتل کر دیا جائے گا۔“ پھر آپ صلی اللہ علیہ وسلم نے فرمایا: ”اس نے کہا: میں آپ کو اس کی مٹی کی خوشبو سونگھاؤں؟ میں نے کہا: جی ہاں۔ پس اس نے اپنا ہاتھ لمبا کیا، مٹی کی مٹھی بھری اور مجھے دے دی۔ میں اپنے آپ پر قابو نہ پا سکا اور رونے لگ گیا۔“","",{"t":"سیدنا حسین رضی اللہ عنہ کی شہادت کی پیشین گوئی","k":"أخرجه أحمد: ۱/۸۵\n(الصحيحة: ۱۱۷۱)","e":"آجکل سیدنا حسین رضی اللہ عنہ کی شہادت کی نسبت سے جن امور کا ارتکاب کیا جا رہا ہے یا ان کو دین میں داخل کر دیا گیا ہے، ان احادیث مبارکہ سے ان کا رد ہوتا ہے، کیونکہ حضرت جبریل نے آپ صلی اللہ علیہ وسلم کے لیے شہادت حسین رضی اللہ عنہ کی ساری صورتحال واضح کر دی تھی، لیکن اس کے باوجود آپ صلی اللہ علیہ وسلم نے اپنے دین میں کسی نئے حکم کا اضافہ نہ کیا۔ سیدنا حسین رضی اللہ عنہ کی میدانِ کربلا میں شہادت امت مسلمہ کے چہرے پر سیاہ دھبہ ہے۔ آپ صلی اللہ علیہ وسلم نے سیدنا جبریل علیہ السلام کے تعاون سے پہلے ہی پیشین گوئی فرما دی تھی۔ امام البانی رحمہ اللہ کہتے ہیں: اس قسم کی احادیث کربلا کے تقدس، اس زمین پر سجدہ کرنے اور اس کی مٹی کی بنائی گئی ٹکیہ پر سجدے کرنے کی فضیلت پر دلالت نہیں کرتیں، جیسا کہ شیعوں کا خیال ہے، اگر اس قسم کی مٹی کی کوئی فضیلت ہوتی تو مسجد حرام اور مسجد نبوی کی مٹی سے بنائی جانی چاہیے تھی۔ اصل میں اس چیز کا تعلق شیعوں کی بدعت اور اہل بیت اور ان کے آثار کی تعظیم میں غلو سے ہے۔ بڑی عجیب و غریب بات ہے کہ ان لوگوں کے ہاں عقل بھی مصادر شریعت میں سے ہے، اسی بنا پر وہ عقلی تحسین اور عقلی تقبیح کے قائل ہیں۔ لیکن اس کے باوجود وہ کربلا کی زمین پر سجدہ کرنے کی فضیلت ایسی روایات سے ثابت کرتے ہیں، جو عقلی تقاضوں کے مطابق بالکل باطل ہیں۔ سید عبد الرضا مرعشی شہرستانی نے اپنے رسالے (ص ۱۵) میں ”السجود علی التربة الحسینیة“ کے عنوان میں لکھا: ”کربلا کی مٹی کے شرف، تقدس اور وہاں مدفون ہستیوں کی طہارت کی وجہ اس پر سجدہ کرنا افضل ہے، عترتِ طاہرہ کے ائمہ علیہم السلام سے مروی روایات اس پر دلالت کرتی ہیں، مثلا: اس (مٹی) پر کیے ہوئے سجدے ساتویں زمین تک نور پیدا کر دیتے ہیں۔ یہ سجدے ساتوں پردوں کو چاک کر دیتے ہیں۔ اللہ تعالی جس طرح اس مٹی پر سجدے کرنے والے کی نماز قبول کرتا ہے، اس طرح دوسروں کی نہیں کرتا۔ حسین کی قبر کی مٹی پر کیا گیا سجدہ زمینوں کو روشن کر دیتا ہے۔“ میں (البانی) کہتا ہوں: ان روایات کا باطل و مردود ہونا ظاہر ہے، اہل بیت کے ائمہ رضی اللہ عنہم ایسی مرویات سے بری ہیں، ان کی سرے سے کوئی سند ہی نہیں ہے کہ محقق علم حدیث اور اصول حدیث کی روشنی میں ان کو پرکھ سکے، کوئی روایت مرسل ہے تو کوئی معضل۔ اسی شیعہ مصنف نے اپنی کتاب کے ورقوں کو کالا کرتے ہوئے مزید کہا: ”حسینی مٹی کی فضیلت و تقدس پر دلالت کرنے والی روایات صرف ائمہ اہلِ بیت سے مروی نہیں ہیں، بلکہ دوسرے اسلامی فرقوں کی بنیادی کتابوں میں بڑی شہرت کے ساتھ ان کا تذکرہ ملتا ہے، ان کے علما اور رواۃ نے ان کو روایات کیا ہے، مثلا امام سیوطی نے اپنی کتاب (الخصائص الکبری) میں (باب اخبار النبی صلی اللہ علیہ وسلم بقتل الحسین علیہ السلام) میں امام حاکم، امام بیہقی، امام ابو نعیم اور امام طبری جیسے ثقات سے تقریباً بیس روایات بیان کی ہیں، اسی طرح امام ہیثمی کے (مجمع الزوائد: ۹/۱۹۱) میں بھی ان کا تذکرہ ملتا ہے۔“ میں (البانی) کہتا ہوں: اے مسلمان! تجھے علم ہونا چاہیے کہ امام سیوطی اور امام ہیثمی نے ایک حدیث بھی ایسی ذکر نہیں کی، جو حسینی مٹی کی فضیلت و تقدس پر دلالت کرے، اہل السنہ کی روایت کردہ احادیث سے صرف یہ ثابت ہوتا ہے کہ آپ صلی اللہ علیہ وسلم نے سیدنا حسین رضی اللہ عنہ کی شہادت کی خبر دی تھی، جیسا کہ میں نے بھی اس صحیحہ میں چند روایات بیان کی ہیں۔ اس شیعے نے جن روایات کے بارے میں دعوی کیا ہے، کیا وہ سیوطی اور ہیثمی نے روایت کی ہیں؟ اے اللہ! ہرگز نہیں۔ در اصل یہ شیعہ اپنی ضلالت اور بدعت کی تائید میں رواں دواں تھا اور مکڑی کے جالے سے کمزور دلیل کا بھی سہارا لینے لگا۔ اس مرعشی شہرسانی شیعے نے اپنی کتاب کے قاریوں کو اتنا دھوکہ دینے پر اکتفا نہیں کیا، بلکہ رسول اللہ صلی اللہ علیہ وسلم پر جھوٹ بولنے کی جرات بھی کرنے لگا، جیسا کہ وہ کہتا ہے: ”جس نے سب سے پہلی مٹی سے بنی ہوئی تختی پر سجدہ کیا، وہ ہمارے نبی حضرت محمد صلی اللہ علیہ وسلم ہیں، یہ اس وقت کی بات ہے، جب ۳ھ میں مسلمانوں اور قریشیوں میں احد والی جنگ لڑی گئی، جس میں رکنِ اسلام حمزہ بن عبد المطلب کی شہادت کا واقعہ پیش آیا۔ اس وقت نبی کریم صلی اللہ علیہ وسلم نے مسلمان عورتوں کو حکم دیا کہ ہر محفلِ سوگ میں ان پر نوحہ کریں، پھر ان کی تکریم میں وسعت اختیار کی گئی اور لوگ ان کی قبر سے مٹی لے کر اس سے تبرک حاصل کرتے اور اس پر سجدہ کرتے اور اس سے سجدہ کی جگہیں بناتے، جیسا کہ (شیعوں کی کتاب) (الارض والتربة الحسینیة) میں ہے۔ میں (البانی) کہتا ہوں: قارئین کرام! سوچیں، اس آدمی نے رسول اللہ صلی اللہ علیہ وسلم کی طرف کیسا جھوٹ منسوب کیا اور یہ دعوی کر دیا کہ نبی کریم صلی اللہ علیہ وسلم نے سب سے پہلے سجدہ کرنے کے لیے تختی بنوائی تھی۔ پھر اس نے اپنے دعوی کی کوئی دلیل بھی پیش نہ کی۔ البتہ یہ جھوٹ پیش کیا کہ آپ صلی اللہ علیہ وسلم نے عورتوں کو سیدنا حمزہ رضی اللہ عنہ پر نوحہ کرنے کا حکم دیا تھا، حالانکہ اس حکم کا مٹی والے مسئلہ سے کوئی ربط بھی نہیں ہے، جبکہ آپ صلی اللہ علیہ وسلم نے تو عورتوں سے نوحہ نہ کرنے کی بیعت لی تھی، جیسا کہ صحیح بخاری اور صحیح مسلم میں سیدہ عطیہ رضی اللہ عنہا کی روایت سے ثابت ہوتا ہے۔ پھر تیسرا جھوٹ یہ پیش کر دیا کہ صحابہ کرام تبرک کے لیے سیدنا حمزہ رضی اللہ عنہ کی قبر سے مٹی اٹھا لیتے اور اس پر سجدہ کرتے تھے۔ یہ صحابہ کرام رضی اللہ عنہم پر واضح جھوٹ ہے۔ وہ اس قسم کی بت پرستی سے کوسوں دور تھے۔ پھر یہ بیچارہ اپنے جھوٹوں کو مسلمانوں کے کسی معروف مصدر کی طرف منسوب بھی نہ کر سکا۔ البتہ (الارض والتربة الحسینیة) کا نام پیش کر دیا، جو ایک شیعی کی کتاب ہے۔ (صحیحہ: ۱۱۷۱) اس کے بعد مزید بحث صحیحہ میں دیکھی جا سکتی ہے۔"}],[3308,"سیدنا ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! جو آدمی ہم اہل بیت سے بغض رکھے گا، اللہ تعالی اسے جہنم میں داخل کرے گا۔“","",{"t":"اہل بیت کی فضیلت","k":"أخرجه الحاكم: ۳/۱۵۰ ، وروى ابن حبان: ۲۲۴۶ نحوه\n(الصحيحة: ۲۴۸۸)"}],[3309,"سیدنا جابر بن عبد اللہ رضی اللہ عنہ سے مروی ہے، وہ کہتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو دورانِ حج عرفہ والے دن دیکھا، آپ صلی اللہ علیہ وسلم اپنے اونٹنی ”قصواء“ پر سوار ہو خطاب کر رہے تھے۔ میں نے آپ صلی اللہ علیہ وسلم کو یہ کہتے ہوئے سنا: ”لوگو! میں تم میں ایسی (دو) چیزیں چھوڑ کر جا رہا ہوں کہ اگر تم نے ان کو تھامے رکھا تو کبھی بھی گمراہ نہیں ہو گے: (۱) اللہ تعالی کی کتاب اور (۲) اپنی نسل یعنی اہل بیت۔“","",{"t":"کتاب اللہ اور اہل بیت معیارِ حق ہیں","k":"أخرجه الترمذي: ۲/۳۰۸ ، والطبراني: ۲۶۸۰\n(الصحيحة: ۱۷۶۱)","e":"امام البانی رحمہ اللہ رقم طراز ہیں: ذی وقار قارئین! معروف بات ہے کہ شیعہ لوگ اس حدیث سے حجت پکڑتے ہیں اور دوسروں کو یوں قائل کرتے ہیں کہ بعض اہل السنہ بھی اس رائے کے ہو کر رہ جاتے ہیں کہ وہ درست ہیں، حقیقت یہ ہے کہ اس سلسلے میں ان سب کو وہم ہوا ہے، ہم اس کی دو پہلووں سے وضاحت کریں گے: (اول) اس حدیث میں آپ صلی اللہ علیہ وسلم کے قول ”وعترتی“ سے مراد آپ صلی اللہ علیہ وسلم کے اہل بیت ہیں، کیونکہ بعض طرق میں اس کی وضاحت موجود ہے، جیسا کہ اسی حدیث میں ”وعترتی اهل بیتی“ کے الفاظ موجود ہیں اور اصل اہل بیت آپ صلی اللہ علیہ وسلم کی بیویاں ہیں، جن میں سیدہ عائشہ صدیقہ رضی اللہ عنہا بھی موجود ہیں، جیسا کہ سورہ احزاب میں ہے: ﴿إِنَّمَا يُرِيدُ اللهُ لِيُذْهِبَ عَنكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا﴾ (سورہ احزاب: ۳۳) ...... ”اللہ تعالی یہی چاہتا ہے کہ اے اہل بیت! تم سے وہ (ہر قسم کی) گندگی کو دور کر دے اور تمھیں خوب پاک کر دے۔“ ہمارے دعوے کی تائید اس آیت کے سیاق و سباق سے ہوتا ہے، ارشادِ باری تعالی ہے: ﴿يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِّنَ النِّسَاءِ إِنِ اتَّقَيْتُنَّ فَلَا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ وَقُلْنَ قَوْلًا مَّعْرُوفًا وَقَرْنَ فِي بُيُوتِكُنَّ وَلَا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الْأُولَى وَأَقِمْنَ الصَّلَاةَ وَآتِينَ الزَّكَاةَ وَأَطِعْنَ اللهَ وَرَسُولَهُ إِنَّمَا يُرِيدُ اللهُ لِيُذْهِبَ عَنكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا وَاذْكُرْنَ مَا يُتْلَى فِي بُيُوتِكُنَّ مِنْ آيَاتِ اللهِ وَالْحِكْمَةِ إِنَّ اللهَ كَانَ لَطِيفًا خَبِيرًا﴾ (سورہ احزاب: ۳۲، ۳۳، ۳۴) ...... ”اے نبی کی بیویو! تم عام عورتوں کی طرح نہیں ہو، اگر تم پرہیز گاری اختیار کرو تو نرم لہجے سے بات نہ کرو کہ جس کے دل میں روگ ہو وہ کوئی خیال کرے اور ہاں قاعدے کے مطابق کلام کرو۔ اور اپنے گھروں میں قرار سے رہو اور قدیمی جاہلیت کے زمانے کی طرح اپنے بناؤ کا اظہار نہ کرو اور نماز ادا کرتی رہو اور زکوۃ دیتی رہو اور اللہ اور اس کے رسول کی پیروی کرو، اللہ تعالی یہی چاہتا ہے کہ اے اہل بیت! تم سے وہ (ہر قسم کی) گندگی کو دور کر دے اور تمھیں خوب پاک کر دے اور تمھارے گھروں میں اللہ کی جو آیتیں اور رسول کی جو احادیث پڑھی جاتی ہیں، ان کا ذکر کرتی رہو، یقیناً اللہ تعالی لطف کرنے والا خبردار ہے۔“ شیعہ لوگوں نے اس آیت میں مذکورہ اہل بیت سے مراد سیدنا علی، سیدہ فاطمہ، سیدنا حسن اور سیدنا حسین رضی اللہ عنہم لیے ہیں اور آپ کی بیویوں کو چھوڑ دیا ہے۔ اصل بات یہ ہے کہ یہ لوگ اپنی خواہشات کے مطابق قرآن مجید میں تحریف کرتے ہیں۔ جس واقعہ کے مطابق آپ صلی اللہ علیہ وسلم نے مذکورہ بالا چار ہستیوں کو چادر میں اکٹھا کیا اور ان کو اہل بیت قرار دیا، اس کا مطلب یہ ہے کہ اس آیت کی دلالت میں توسیع کی گئی، جیسا کہ حافظ ابن کثیر وغیرہ نے وضاحت کی۔ یہی معاملہ ”وعترتی“ والی حدیث کا ہے، کہ اس سے مراد آپ صلی اللہ علیہ وسلم کے اہل بیت ہیں، جن میں امہات المومنین اور سیدنا علی اپنے اہل سمیت داخل ہیں۔ توربشتی نے کہا: آدمی کی ”عترت“ سے مراد اس کے اہل بیت اور اور انتہائی قریبی رشتہ دار ہوتے ہیں۔ جب آپ صلی اللہ علیہ وسلم نے ”اھل بیتی“ فرما کر وضاحت کی تو معلوم ہو گیا کہ آپ اپنی نسل، قریب تر رشتہ دار اور بیویاں مراد لینا چاہتے ہیں۔ (دوم)..... آپ صلی اللہ علیہ وسلم کے اہل بیت سے مراد امت کے وہ علما ہیں، جو نیک، صالح اور کتاب وسنت پر عمل کرنے والے ہیں، جیسا کہ امام ابو جعفر طحاوی رحمہ اللہ تعالی نے کہا: ”عترت“ سے مراد آپ صلی اللہ علیہ وسلم کے اہل بیت، آپ کے دین کے پیروکار اور آپ کے حکم کی پابندی کرنے والے ہیں۔ شیخ ملا علی قاری نے بھی اسی قسم کا معنی بیان کیا ہے۔ پھر انھوں نے اس حدیث میں اہل بیت کو خاص کرنے کی وجہ پر روشنی ڈالتے ہوئے کہا: زیادہ تر یہ دیکھا گیا ہے کہ گھر کے سربراہ کو اور اس کے احوال کو زیادہ جاننے والے اس کے اہل بیت ہوتے ہیں، جن سے مراد وہ اہل علم ہیں، جو آپ صلی اللہ علیہ وسلم کی سیرت و کردار، حکم و حکمت اور طرز و طریقہ پر مطلع تھے۔ اس معنی میں ”اہل بیت“ قرآن مجید کے مقابلے میں ذکر کیا گیا، جیسا کہ اللہ تعالی نے فرمایا: ﴿وَيُعَلِّمُهُمُ الْكِتَابَ وَالْحِكْمَةَ (سورہ جمعہ: ۲) ...... ”وہ رسول ان کو کتاب اور حکمت (یعنی احادیث رسول) کی تعلیم دیتا ہے۔“ میں (البانی) کہتا ہوں: سورہ احزاب کی آیاتِ تطہیر میں امہات المومنین سے خطاب کرتے ہوئے کہا گیا: ﴿وَاذْكُرْنَ مَا يُتْلَى فِي بُيُوتِكُنَّ مِنْ آيَاتِ اللهِ وَالْحِكْمَةِ إِنَّ اللهَ كَانَ لَطِيفًا خَبِيرًا﴾ (سورہ احزاب: ۳۴) ...... ”اور تمھارے گھروں میں اللہ کی جو آیتیں اور رسول کی جو احادیث پڑھی جاتی ہیں، ان کا ذکر کرتی رہو، یقیناً اللہ تعالی لطف کرنے والا خبردار ہے۔“ یعنی اس آیت میں حکمت سے مراد احادیث رسول ہیں۔ اس بحث سے معلوم ہوا کہ ”اہل بیت“ سے مراد آپ صلی اللہ علیہ وسلم کی سنت کو تھامنے والے ہیں، حدیث میں یہی مقصود بالذات ہیں، اسی معنی میں سیدنا زید بن ارقم رضی اللہ عنہ کی حدیث میں مذکور ”ثقلین“ سے مراد قرآن مجید اور اہل بیت مراد ہیں۔ ابن اثیر نے (النھایۃ) میں کہا: آپ صلی اللہ علیہ وسلم نے اس کو ”ثقلین“ کہا، کیونکہ کتاب وسنت کو حرزِ جان بنانا اور ان پر عمل کرنا ثقیل اور مشکل کام ہے اور ہر خطرناک اور عمدہ چیز کو ”ثقل“ کہتے ہیں، آپ صلی اللہ علیہ وسلم نے ان دو کی قدر کو عظیم ثابت کرنے کے لیے ان کو ”ثقلین“ کہا۔ راقم الحروف کہتا ہے: امام البانی کی مراد درج ذیل حدیث ہے: آپ صلی اللہ علیہ وسلم نے فرمایا: «وَأَنَا تَارِكٌ فِيكُمْ ثَقَلَيْنِ: أَوَّلُهُمَا كِتَابُ اللهِ ...... وَأَهْلَ بَيْتِي، أُذَكِّرُكُمُ اللهَ فِي أَهْلِ بَيْتِي -» ...... (مسلم: ۲۴۰۸) ”میں تم میں دو نفیس (اور بیش قیمت) چیزیں چھوڑنے والا ہوں: اللہ کی کتاب ...... اور میرے اہل بیت، میں اپنے اہل بیت کے بارے میں تم کو اللہ تعالی کا واسطہ دیتا ہوں، ......“ میں (البانی) کہتا ہوں: اس باب کی حدیث میں قرآن مجید کے ساتھ اہل بیت کا ذکر کرنے کا وہی مفہوم ہے، جو سنت رسول کے ساتھ خلفائے راشدین کی سنت کا ہے۔ شیخ ملا علی قاری نے کہا: خلفائے راشدین کا تذکرہ کرنے کا مطلب یہ ہے کہ انھوں نے آپ صلی اللہ علیہ وسلم کی سنت پر ہی عمل کیا، ان کی طرف اس کی اضافت یا تو ان کے عمل کی وجہ سے ہے یا اس بنا پر کہ وہ سنت کو اختیار کرتے ہیں اور اس سے استدلال کرتے ہیں۔ سابقہ بحث سے معلوم ہوا کہ یہ حدیث موطا کی درج ذیل روایت کا قوی شاہد ہے: «تَرَكْتُ فِيكُمْ أَمْرَيْنِ لَنْ تَضِلُّوا مَا تَمَسَّكْتُمْ بِهِمَا؛ كِتَابَ اللهِ وَسُنَّةَ رَسُولِهِ» ...... ”میں نے تم میں دو چیزیں چھوڑیں، اگر تم نے ان کو تھامے رکھا تو ہر گز گمراہ نہ ہو گے، ایک اللہ کی کتاب اور دوسری اس کے رسول کی سنت۔“ یہ روایت مشکوۃ (۱۸۶) میں بھی ہے۔ جن لوگوں نے موطا کی روایت کو ضعیف ثابت کرنے کے لیے اوراق سیاہ کیے، ان بیچاروں کو اس شاہد کی اس صورت کا علم نہیں تھا۔ واللہ المستعان۔ (صحیحہ: ۱۷۶۱)"}],[3310,"سیدنا عبداللہ بن عباس رضی اللہ عنہما بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”حضرت مریم بنت عمران کے بعد جنتی عورتوں کی سردار یہ (تین عورتیں ہیں:) فاطمہ، خدیجہ اور فرعون کی بیوی آسیہ تھیں۔“","",{"t":"سیدہ آسیہ اور سیدہ مریم علیہما السلام کی فضیلت","k":"رواه الطبراني: ۳/۲/۱۵۰\n(الصحيحة: ۱۴۲۴)"}],[3311,"نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”میں نے جعفر بن ابو طالب کو بادشاہ کے روپ میں دیکھا، وہ جنت میں فرشتوں کے ساتھ دو پروں کے سہارے اڑ رہا تھا۔“ یہ حدیث سیدنا ابو ہریرہ، سیدنا عبداللہ بن عمر، سیدنا عبداللہ بن عباس، سیدنا علی بن ابو طالب، سیدنا ابو عامر اور سیدنا براء رضی اللہ عنہم سے مروی ہے۔","",{"t":"سیدنا جعفر بن ابو طالب رضی اللہ عنہ کی فضیلت","k":"(۱) - أما حديث أبي هريرة؛ فأخرجه الترمذي: ۲/۳۰۵ ، وأبو يعلى: ۴/۱۵۲۸ ، والحاكم: ۳/۲۰۹ ، (۲) - وأما حديث ابن عمر؛ فأخرجه البخاري: ۷/۶۲ ، والطبراني: ۱/۱۵۰/۲ ، (۳) - وأما حديث ابن عباس؛ فأخرجه أبو بكر الشافعي في \"الفوائد\": ۱/۱۳/۱۹ ، وابن عدي: ۲/۱۵۰/۲ ، والحاكم: ۳/۱۹۶ ، والطبراني: ۱/۱۵۰/۲ ، (۴) - وأما حديث علي بن أبي طالب؛ فأخرجه ابن سعد: ۴/۳۹ ، والحاكم: ۳/۲۱۲ ، (۵) - وأما حديث أبي عامر؛ فأخرجه ابن سعد: ۲/۱۲۹ ، (۶) - وأما حديث البراء ابن عازب؛ فأخرجه الحاكم: ۳/۴۰\n(الصحيحة: ۱۲۲۶)"}],[3312,"سیدنا جابر رضی اللہ عنہ کہتے ہیں کہ جب سیدنا جعفر رضی اللہ عنہ حبشہ سے آئے تو نبی صلی اللہ علیہ وسلم نے ان کا معانقہ کیا۔","",{"t":"سیدنا جعفر بن ابو طالب رضی اللہ عنہ کی فضیلت","k":"أخرجه أبو يعلى في \"مسنده\": ۳/۳۹۸/۱۸۷۶ ، والطحاوي في \"شرح المعاني\": ۴/۲۸۱\n(الصحيحة: ۲۶۵۷)"}],[3313,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے: ”بھلائی تو آخرت کی ہی بھلائی ہے۔“ یا یوں فرمایا: ”اے اللہ! بھلائی نہیں ہے مگر آخرت کی بھلائی پس تو انصاریوں اور مہاجروں کو بخش دے۔“","",{"t":"صحابہ کرام کی فضیلت","k":"أخرجه أحمد: ۳/۱۶۹ ، وأخرجه البخاري: ۳۷۹۵، ۳۷۹۶، ومسلم: ۵/۱۸۸ وغيرهما\n(الصحيحة: ۳۱۹۸)"}],[3314,"نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”جب میرے صحابہ کا تذکرہ ہونے لگے تو خاموش رہنا، جب ستاروں کا ذکر ہونے لگے تو خاموش رہنا اور جب تقدیر کے مسئلے کا ذکر ہونے لگے تو خاموش رہنا۔“ یہ حدیث سیدنا عبد اللہ بن مسعود، سیدنا ثوبان، سیدنا عبد اللہ بن عمر رضی اللہ عنہم اور طاووس سے مرسلاً روایت کی گئی ہے۔","",{"t":"صحابہ کرام کی فضیلت","k":"كلها ضعيفة الاسانيد ولكن بعضها يشد بعضا - ۱ - أما حديث ابن مسعود؛ فأخرجه الطبراني في \"الكبير\" ۲/۲/۷۸ ، وأبو نعيم في \"الحلية\": ۴/۱۰۸ ، ۲ - أما حديث ثوبان؛ فأخرجه أبو طاهر الزيادي في \"ثلاثة مجالس من الأمالي\": ۲/۱۹۱ ، والطبراني في \"الكبير\" ۱/۷۱/۲ ، ۳ - وأما حديث ابن عمر؛ فأخرجه ابن عدي: ۱/۲۹۵ ، وعنه السهمي في \"تاريخ جرجان\": ۳۱۵ ، ۴ - ثم وجدت للحديث شاهدا مرسلا عن طاؤوس أخرجه عبدالرزاق في \"الأمالي\": ۲/۱/۳۹\n(الصحيحة: ۳۴)","e":"معلوم ہوا کہ صحابہ کرام کے معائب و نقائص کو نظر انداز کر دینا چاہیے، صحابہ سے ہونے والی خطا کے بارے میں ہمارا نظریہ کیا ہونا چاہیے؟ اس موضوع پر ”الْفِتَنُ وَ اَشْرَاطُ السَّاعَةِ وَالْبَعْثُ“ میں ”سیدنا علی رضی اللہ عنہ حق پر تھے“ اور ”مشاجرات صحابہ کے بارے میں متأخرین کو کیا کہنا چاہیے؟“ کے عنوانوں میں تفصیلی بحث کی گئی ہے۔ امید یہی ہے کہ ان کے نیکیوں کے سمندر ان کی بشری لغزشوں کے قطروں کے اثرات کو زائل کر دیں گے۔ نہ علم نجوم میں دلچسپی لینی چاہیے اور نہ تقدیر کے بارے میں زیادہ غور و خوض کرنا چاہیے۔ ان دونوں موضوعات پر ”الْأَيْمَانُ وَالتَّوْحِيدُ وَالدِّينُ وَالْقَدْرُ“ میں تفصیلی بحثیں موجود ہیں۔"}],[3315,"بکر بن عبد اللہ کہتے ہیں کہ اصحاب رسول تربوز (یا خربوزے) کے چھلکے (یا ان دونوں کی بیلیں) ایک دوسرے کو مار کر مزاح کرتے تھے، لیکن جب حقیقت میں (دشمنوں سے گھمسان کے رن) پڑتے تو وہ سخت جنگجو ثابت ہوتے۔","",{"t":"صحابہ کرام کی فضیلت","k":"أخرجه البخاري في \"الأدب المفرد\": ۲۶۶\n(الصحيحة: ۴۳۵)","e":"نبی کریم صلی اللہ علیہ وسلم کے عہد مبارک میں اور خلافت راشدہ میں ہونے والی جنگوں میں صحابہ کرام نے بہادری و دلیری کے وہ ثبوت فراہم کیے کہ مخالفین انگشت بدنداں ہو کر رہ گئے۔"}],[3316,"سیدنا عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے میرے صحابہ کو گالیاں دیں، اس پر اللہ تعالیٰ، فرشتوں اور تمام لوگوں کی لعنت ہوگی۔“","",{"t":"صحابہ کو برا بھلا کہنے والا ملعون ہے","k":"رواه الطبراني: ۳/۱۷۴/۱\n(الصحيحة: ۲۳۴۰)","e":"کیا کوئی عبرت حاصل کرنے والا ہے؟"}],[3317,"ابو زبیر، سیدنا جابر رضی اللہ عنہ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ایسے آدمی کے پاس سے گزرے جو الٹ پلٹ ہو رہا تھا۔ آپ نے اس کے بارے میں پوچھا؟ صحابہ نے کہا: اے اللہ کے نبی! یہ روزے دار ہے۔ آپ نے اسے بلایا اور روزہ افطار کرنے کا حکم دیا اور فرمایا: ”کیا تجھے یہ (نیک عمل) کافی نہیں ہے کہ تو رسول اللہ کی صحبت میں اللہ تعالیٰ کے راستے میں ہے کہ تو نے روزہ رکھنا بھی شروع کر دیا۔“","",{"t":"آپ صلی اللہ علیہ وسلم کی صحبت کی فضیلت","k":"أخرجه أحمد: ۳/۳۲۷ ، وله طرق اخرى عن جابر بنحوه في \"الصحيحين\" وغيرهما\n(الصحيحة: ۲۵۹۵)","e":"اس میں جہادی سفر اور رسول اللہ صلی اللہ علیہ وسلم کی صحبت کی فضیلت کا بیان ہے۔ امام البانی رحمہ اللہ نے کہا: اس حدیث مبارکہ میں بڑی واضح دلالت موجود ہے اس وقت سفر میں روزہ رکھنا ناجائز ہو گا، جب مسافر کو اس کی وجہ سے تکلیف ہوگی، اسی پر آپ صلی اللہ علیہ وسلم کی درج ذیل دو احادیث پر محمول کیا جائے گا: «لَيْسَ مِنَ الْبِرِّ الصِّيَامُ فِي السَّفَرِ -» ...... ”سفر میں روزہ رکھنا نیکی نہیں ہے۔“ اور آپ صلی اللہ علیہ وسلم نے سفر میں روزہ نہ توڑنے والوں کے بارے میں کہا تھا: «أُولَئِكَ الْعُصَاةُ -» ...... ”یہی لوگ نافرمان ہیں۔“ جس آدمی کو دورانِ سفر روزہ رکھنے کی وجہ سے تکلیف نہ ہو رہی ہو تو اسے روزہ رکھنے اور نہ رکھنے کا اختیار ہے، یہ اس باب کی مختلف احادیث کا خلاصہ اور جمع و تطبیق ہے۔ (صحیحہ: ۲۵۹۵) اس موضوع پر مفصل بحثیں ”الصیام والقیام“ میں دیکھی جا سکتی ہیں۔"}],[3318,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میری امت پر سب سے زیادہ رحم کرنے والے ابو بکر، اللہ تعالیٰ کے احکام کے معاملے میں سب سے زیادہ سخت عمر، سب سے زیادہ حیا کرنے والے عثمان، اللہ تعالیٰ کی کتاب کو سب سے زیادہ پڑھنے والے ابی بن کعب، فرائض (یا علم میراث) کو سب سے زیادہ جاننے والے زید بن ثابت اور حلال و حرام کی سب سے زیادہ پہچان رکھنے والے معاذ بن جبل ہیں۔ آگاہ ہو جاؤ! ہر امت کا ایک امین ہوتا ہے اور اس امت کا امین ابو عبیدہ بن الجراح ہے۔“","",{"t":"صحابہ کی مخصوص اغلمی صفات","k":"أخرجه الترمذي: ۲/۳۰۹ ، وابن ماجه: ۱۵۴ ، وابن حبان: ۲۲۱۸، ۲۲۱۹ ، والحاكم: ۳/۴۲۲ ، واحمد ۳/۱۸۴ ، واحمد: ۳/۲۸۰ ، والجملة الاخيرة رواها البخاري: ۷/۷۳ ، ومسلم: ۷/۱۲۹\n(الصحيحة: ۱۲۲۴)","e":"اس میں سات صحابہ کرام کی اغلمی صفات بیان کی گئیں ہیں۔"}],[3319,"رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میرے بعد ابو بکر اور عمر کی پیروی کرنا، عمار کی سیرت اختیار کرنا اور ابن مسعود کے عہد کو تھام لینا۔“ یہ حدیث سیدنا عبد اللہ بن مسعود، سیدنا حذیفہ بن یمان، سیدنا انس بن مالک اور سیدنا عبد اللہ بن عمر رضی اللہ عنہم سے روایت کی گئی ہے۔","",{"t":"صحابہ کی مخصوص اغلمی صفات","k":"۱ - أما حديث ابن مسعود: فأخرجه الترمذي: ۲/۳۱۱ ، والحاكم: ۳/۷۵ ، ۲ - وأما حديث حذيفة: أخرجه الترمذي: ۲/۲۹۰ ، والطحاوي في \"المشكل\" ۲/۸۳-۸۴ ، وأحمد: ۵/۳۸۵، ۴۰۲ ، والحميدي في \"مسنده\" ۱/۲۱۴/۲۴۹ ، وابن سعد: ۲/۳۳۴، و ۲، وابن أبي عاصم في \"السنة\" ۱۰۴۸ و ۱۰۴۹ - بتحقيقي، وأبو نعيم في \"الحلية\" ۹/۱۰۹، و الخطيب: ۱۲/۲۰ ، والحاكم: ۳/۷۵، وابن عساكر: ۹/۳۲۳/۱ و ۱۲/۳۱/۱ مختصرا و مطولا، وبعضم ذكر المولى، وبعضم لم يذكره، وهو الذي رجحه الحاكم خلافا لأبي حاتم في: العلل ۲/۳۸۱ ، ۳ - وأما حديث أنس بن مالك: فأخرجه ابن عدي: ۱/۷۵ ، ۴ - وأما حديث ابن عمر: فأخرجه ابن عساكر: ۹/۳۲۳/۲\n(الصحيحة: ۱۲۳۳)","e":"دوسری احادیث کی روشنی میں یہ کہنا درست ہے کہ خلفائے راشدین اور صحابہ کرام کی اطاعت کی جائے گی، جب تک اللہ تعالیٰ اور رسول اللہ صلی اللہ علیہ وسلم کی نافرمانی نہ ہو۔"}]])